insert into questions (id, exam, topic_id, status, difficulty, stem, lead_in, tags) values
('e3000000-0000-0000-0000-000000000001', 'ukmla', '8d54a4e2-b8b2-4f45-a133-a7652815561e',
insert into question_options (question_id, label, option_text, is_correct, rationale, sort_order) values
('e3000000-0000-0000-0000-000000000001', 'A', 'Diazepam regularly for at least 3 months', false, 'Ruled out because benzodiazepines are not recommended for long-term treatment of GAD due to dependence risk; they are reserved for short-term crisis management only.', 1),
('e3000000-0000-0000-0000-000000000001', 'B', 'Propranolol as sole long-term treatment', false, 'Ruled out because beta-blockers only address peripheral autonomic symptoms (tremor, palpitations) and do not treat the underlying psychological disorder; they are not first-line for GAD.', 2),
('e3000000-0000-0000-0000-000000000001', 'C', 'Quetiapine', false, 'Ruled out because antipsychotics are not first-line treatment for GAD and expose the patient to unnecessary metabolic and extrapyramidal side effects.', 3),
('e3000000-0000-0000-0000-000000000001', 'D', 'Sertraline', true, 'Correct. An SSRI such as sertraline is recommended first-line pharmacological treatment for generalised anxiety disorder when guided self-help and psychological therapy (e.g. CBT) have not been sufficient or are declined.', 4),
('e3000000-0000-0000-0000-000000000001', 'E', 'Referral for inpatient psychiatric admission', false, 'Ruled out because this presentation is manageable in primary care; there is no indication of risk to self or others or severity requiring admission.', 5),
('e3000000-0000-0000-0000-000000000002', 'A', 'Panic disorder', true, 'Correct. Recurrent, unexpected panic attacks with intense fear peaking within minutes, associated anticipatory anxiety and avoidance behaviour (agoraphobic avoidance of the situation where an attack occurred), with normal cardiac workup, is characteristic of panic disorder.', 1),
('e3000000-0000-0000-0000-000000000002', 'B', 'Acute coronary syndrome', false, 'Ruled out because the ECG and troponin are normal and there is a clear recurrent pattern with situational avoidance, making a cardiac cause unlikely; cardiac causes should always be excluded first but are not supported here.', 2),
('e3000000-0000-0000-0000-000000000002', 'C', 'Generalised anxiety disorder', false, 'Ruled out because GAD is characterised by persistent, pervasive worry across many domains rather than discrete, sudden episodes of intense fear peaking within minutes.', 3),
('e3000000-0000-0000-0000-000000000002', 'D', 'Social anxiety disorder', false, 'Ruled out because social anxiety disorder involves fear specifically related to scrutiny in social/performance situations, not discrete unprovoked panic attacks on transport.', 4),
('e3000000-0000-0000-0000-000000000002', 'E', 'Somatic symptom disorder', false, 'Ruled out because this describes persistent worry about physical symptoms and health, not discrete panic attacks with autonomic surge and avoidance.', 5),
('e3000000-0000-0000-0000-000000000003', 'A', 'Clozapine', false, 'Ruled out because clozapine is reserved for treatment-resistant schizophrenia and is not indicated or appropriate first-line treatment for OCD.', 1),
('e3000000-0000-0000-0000-000000000003', 'B', 'Lorazepam as regular daily treatment', false, 'Ruled out because benzodiazepines are not effective long-term treatments for OCD and carry dependence risk; they have no established first-line role here.', 2),
('e3000000-0000-0000-0000-000000000003', 'C', 'Cognitive behavioural therapy with exposure and response prevention (ERP)', true, 'Correct. CBT incorporating ERP is first-line treatment for OCD of mild-to-moderate severity, helping the patient tolerate the anxiety of exposure to triggers without performing the compulsion.', 3),
('e3000000-0000-0000-0000-000000000003', 'D', 'Deep brain stimulation', false, 'Ruled out because this is an invasive, highly specialist intervention reserved for severe, treatment-refractory OCD, not appropriate as an initial step.', 4),
('e3000000-0000-0000-0000-000000000003', 'E', 'Reassurance and review in 6 months with no active intervention', false, 'Ruled out because her OCD is causing significant functional impairment (missing lectures, hours of compulsions) and warrants active treatment now, not watchful waiting.', 5),
('e3000000-0000-0000-0000-000000000004', 'A', 'Watchful waiting with no active intervention for 3 months', false, $x$Ruled out because watchful waiting is only appropriate for mild symptoms present for less than 4 weeks after trauma; this patient's symptoms are significant and have persisted for 5 weeks, warranting active treatment.$x$, 1),
('e3000000-0000-0000-0000-000000000004', 'B', 'Benzodiazepines as first-line and only treatment', false, 'Ruled out because benzodiazepines are not recommended for PTSD as they do not address the underlying condition, carry dependence risk, and may worsen outcomes.', 2),
('e3000000-0000-0000-0000-000000000004', 'C', 'Long-term inpatient psychiatric admission', false, 'Ruled out because there is no indication of risk to self or others requiring admission; PTSD is typically managed in the community with psychological therapy.', 3),
('e3000000-0000-0000-0000-000000000004', 'D', 'Advise him to avoid discussing the event to prevent re-traumatisation', false, 'Ruled out because avoidance perpetuates PTSD symptoms; effective treatment (trauma-focused CBT) works by structured, supported processing of the traumatic memory, not avoidance.', 4),
('e3000000-0000-0000-0000-000000000004', 'E', 'Trauma-focused cognitive behavioural therapy', true, 'Correct. Trauma-focused CBT (or EMDR) is first-line treatment for PTSD; watchful waiting may be appropriate only for mild symptoms present less than 4 weeks, but this patient has significant, functionally impairing symptoms beyond one month.', 5),
('e3000000-0000-0000-0000-000000000005', 'A', 'Somatic symptom disorder', false, 'Ruled out because somatic symptom disorder requires one or more distressing somatic symptoms as the focus, whereas this man has minimal physical symptoms and his preoccupation is with the idea of having an illness rather than the symptoms themselves.', 1),
('e3000000-0000-0000-0000-000000000005', 'B', 'Illness anxiety disorder (health anxiety)', true, 'Correct. Persistent preoccupation with having or acquiring a serious illness, with minimal or no somatic symptoms, high health-related anxiety, and excessive health-related behaviours (checking, reassurance-seeking) despite appropriate negative investigations, is characteristic of illness anxiety disorder.', 2),
('e3000000-0000-0000-0000-000000000005', 'C', 'Malingering', false, 'Ruled out because malingering involves deliberate fabrication of symptoms for external gain (e.g. financial, avoiding work); there is no suggestion of secondary gain here, and his distress appears genuine.', 3),
('e3000000-0000-0000-0000-000000000005', 'D', 'Factitious disorder', false, 'Ruled out because factitious disorder involves deliberately producing or feigning symptoms/signs to assume the sick role, which is not described here.', 4),
('e3000000-0000-0000-0000-000000000005', 'E', 'Colorectal cancer requiring repeat colonoscopy', false, 'Ruled out because he has already had a normal colonoscopy, FIT test, and bloods with no red flag symptoms; repeating investigations would reinforce his anxiety-driven behaviour rather than address the underlying disorder.', 5),
('e3000000-0000-0000-0000-000000000006', 'A', 'Referral to as many specialists as required until a diagnosis is found', false, 'Ruled out because extensive appropriate investigation has already been normal; further specialist referrals reinforce health-seeking behaviour and delay appropriate psychological treatment.', 1),
('e3000000-0000-0000-0000-000000000006', 'B', 'Tell her the symptoms are not real and no further care is needed', false, $x$Ruled out because this is dismissive, damages the therapeutic relationship, and the patient's distress and symptoms are genuinely experienced even without an organic cause.$x$, 2),
('e3000000-0000-0000-0000-000000000006', 'C', 'Long-term high-dose opioid analgesia', false, 'Ruled out because opioids are not indicated for functional somatic symptoms, carry dependence risk, and do not address the underlying disorder.', 3),
('e3000000-0000-0000-0000-000000000006', 'D', 'Admission for inpatient extensive re-investigation of all systems', false, 'Ruled out because she has already had thorough appropriate investigation; further re-investigation is not indicated and risks reinforcing symptom-focused behaviour.', 4),
('e3000000-0000-0000-0000-000000000006', 'E', 'A single consistent GP coordinating care with CBT and regular scheduled review, avoiding unnecessary repeat investigations', true, 'Correct. Somatic symptom disorder is best managed with continuity of care from a single clinician, psychological therapy (CBT), and regularly scheduled (not symptom-contingent) reviews, which reduces reinforcement of illness behaviour and unnecessary repeat investigation.', 5),
('e3000000-0000-0000-0000-000000000007', 'A', 'Generalised anxiety disorder', false, 'Ruled out because GAD involves pervasive worry across many life domains rather than fear specific to social/performance scrutiny situations.', 1),
('e3000000-0000-0000-0000-000000000007', 'B', 'Panic disorder', false, 'Ruled out because panic disorder involves recurrent unexpected panic attacks rather than anxiety specifically tied to social evaluation.', 2),
('e3000000-0000-0000-0000-000000000007', 'C', 'Social anxiety disorder', true, 'Correct. Marked, persistent fear of social or performance situations where scrutiny by others is possible, with anticipated embarrassment, avoidance, and functional impairment lasting more than 6 months, is characteristic of social anxiety disorder.', 3),
('e3000000-0000-0000-0000-000000000007', 'D', 'Autism spectrum disorder', false, 'Ruled out because there is no described history of childhood-onset social communication difficulties or restricted/repetitive behaviours; this presentation is specifically fear of negative judgement, consistent with social anxiety.', 4),
('e3000000-0000-0000-0000-000000000007', 'E', 'Agoraphobia', false, 'Ruled out because agoraphobia is fear of situations where escape might be difficult or help unavailable (e.g. open spaces, crowds, travel), not specifically fear of social scrutiny.', 5),
('e3000000-0000-0000-0000-000000000008', 'A', 'Graded exposure therapy', true, 'Correct. Graded exposure therapy (a form of behavioural therapy) is first-line and highly effective treatment for specific phobia, systematically and progressively exposing the patient to the feared stimulus to reduce the fear response.', 1),
('e3000000-0000-0000-0000-000000000008', 'B', 'Long-term daily benzodiazepine', false, 'Ruled out because benzodiazepines are not first-line or appropriate for long-term management of specific phobia due to dependence risk and lack of durable benefit; they do not treat the underlying phobia.', 2),
('e3000000-0000-0000-0000-000000000008', 'C', 'Lifelong avoidance of all medical procedures involving needles', false, 'Ruled out because avoidance reinforces and maintains the phobia and is clinically unsafe, preventing necessary healthcare (vaccination, blood tests, cannulation).', 3),
('e3000000-0000-0000-0000-000000000008', 'D', 'Antipsychotic medication', false, 'Ruled out because antipsychotics have no role in the treatment of specific phobia.', 4),
('e3000000-0000-0000-0000-000000000008', 'E', 'General anaesthesia for all future blood tests', false, 'Ruled out because this is impractical, carries unnecessary anaesthetic risk, and does not address the underlying phobia, unlike exposure-based psychological therapy.', 5),
('e3000000-0000-0000-0000-000000000009', 'A', 'Immediate intravenous lorazepam', false, 'Ruled out because benzodiazepines are not first-line for acute panic attacks and their routine use in the emergency department risks reinforcing panic behaviour and dependence; non-pharmacological measures should be tried first.', 1),
('e3000000-0000-0000-0000-000000000009', 'B', 'Calm reassurance, a quiet environment, and controlled/slow breathing techniques', true, 'Correct. Once organic causes have been reasonably excluded (as here, with a known diagnosis and normal ECG), the acute panic attack is managed with reassurance, a calm environment, and breathing control techniques to reduce hyperventilation and its associated paraesthesia; this avoids reinforcing panic behaviour with unnecessary intervention or medication.', 2),
('e3000000-0000-0000-0000-000000000009', 'C', 'Emergency coronary angiography', false, 'Ruled out because she has a known diagnosis of panic disorder with previous identical, fully investigated episodes and a currently reassuring ECG; angiography is not indicated for a recurrent, already-characterised presentation.', 3),
('e3000000-0000-0000-0000-000000000009', 'D', 'Rebreathing into a paper bag as the definitive treatment', false, 'Ruled out because paper bag rebreathing is an outdated technique with limited evidence and risk (e.g. worsening hypoxia if misapplied); it is not the recommended approach.', 4),
('e3000000-0000-0000-0000-000000000009', 'E', 'Admission for psychiatric sectioning under the Mental Health Act', false, 'Ruled out because there is no evidence of risk to herself or others or a mental disorder requiring detention; a panic attack does not meet criteria for involuntary detention.', 5),
('e3000000-0000-0000-0000-000000000010', 'A', 'Proceed only once he regains capacity, however long that takes', false, 'Ruled out because this may be a time-critical decision where delay could cause harm; best interests decisions must be made without unreasonable delay when a decision cannot wait for capacity to return.', 1),
('e3000000-0000-0000-0000-000000000010', 'B', 'Ask his next of kin to sign a consent form on his behalf', false, 'Ruled out because in England and Wales relatives cannot give proxy consent for medical treatment unless they hold a valid Lasting Power of Attorney for health and welfare; consent is a best-interests clinical decision, not a family signature.', 2),
('e3000000-0000-0000-0000-000000000010', 'C', 'Detain him under Section 3 of the Mental Health Act to enable treatment', false, 'Ruled out because the Mental Health Act is used to treat mental disorder, not to authorise treatment for a physical health condition in a patient lacking capacity; the Mental Capacity Act framework applies here.', 3),
('e3000000-0000-0000-0000-000000000010', 'D', 'Make a decision in his best interests, involving family and the wider clinical team where possible', true, 'Correct. Once a two-stage capacity assessment confirms he lacks capacity for this specific decision (due to his stroke affecting his ability to understand, retain, weigh, or communicate information) and there is no valid advance decision or attorney, treatment decisions must be made in his best interests under the Mental Capacity Act 2005, taking into account his known wishes, values, and input from family/carers where practicable.', 4),
('e3000000-0000-0000-0000-000000000010', 'E', 'Withhold all treatment until a court order is obtained', false, 'Ruled out because most best-interests decisions, including this one, do not require court involvement; court authorisation is reserved for specific contested or particularly serious/irreversible decisions.', 5),
('e3000000-0000-0000-0000-000000000011', 'A', $x$The eldest family member's wishes should automatically be followed$x$, false, $x$Ruled out because family members do not have automatic decision-making authority (without a valid LPA); the decision must be made in the patient's best interests, considering but not simply deferring to family preference.$x$, 1),
('e3000000-0000-0000-0000-000000000011', 'B', 'Proceed with whichever option the GP prefers without further discussion', false, 'Ruled out because unilateral decision-making without appropriate consultation and, where there is unresolved dispute, appropriate escalation is not in line with best-interests process.', 2),
('e3000000-0000-0000-0000-000000000011', 'C', 'Detain her under Section 2 of the Mental Health Act to resolve the placement dispute', false, 'Ruled out because the Mental Health Act is for assessment/treatment of mental disorder, not for resolving disputes about capacity-related welfare/placement decisions.', 3),
('e3000000-0000-0000-0000-000000000011', 'D', 'Refer to the Court of Protection for a ruling', true, 'Correct. Where there is genuine, unresolved disagreement about a best-interests decision that significantly affects a person lacking capacity (such as contested residence), and it cannot be resolved through discussion, referral to the Court of Protection is appropriate to make a legally binding decision.', 4),
('e3000000-0000-0000-0000-000000000011', 'E', 'No action is needed as the disagreement will resolve itself over time', false, $x$Ruled out because an unresolved best-interests dispute affecting a vulnerable patient's care needs active resolution, not indefinite delay.$x$, 5),
('e3000000-0000-0000-0000-000000000012', 'A', 'Section 3 (admission for treatment)', false, 'Ruled out because Section 3 is used when the diagnosis and treatment plan are already established and the primary need is for treatment rather than assessment; this presentation, with recent relapse requiring assessment, is more appropriately managed initially under Section 2.', 1),
('e3000000-0000-0000-0000-000000000012', 'B', 'Section 2 (admission for assessment)', true, 'Correct. Section 2 allows compulsory admission for assessment (and treatment if needed) for up to 28 days when the diagnosis is unclear or the patient has not been assessed/treated before in this way, which fits a relapse with uncertain current risk requiring inpatient assessment; it requires two doctors (one Section 12 approved) and an Approved Mental Health Professional (AMHP).', 2),
('e3000000-0000-0000-0000-000000000012', 'C', $x$Section 5(2) (doctor's holding power)$x$, false, 'Ruled out because Section 5(2) applies only to a patient who is already a voluntary inpatient in hospital, allowing a doctor to hold them for up to 72 hours pending a full Mental Health Act assessment; this patient is not currently a hospital inpatient.', 3),
('e3000000-0000-0000-0000-000000000012', 'D', 'Section 136 (removal from a public place by police)', false, 'Ruled out because Section 136 applies to police powers to remove a person who appears to have a mental disorder from a public place to a place of safety; he has been brought in by family, not detained by police from a public place.', 4),
('e3000000-0000-0000-0000-000000000012', 'E', 'No section is required as he can be persuaded informally', false, 'Ruled out because he is actively refusing admission despite significant risk from untreated psychosis, and informal persuasion has already failed; formal detention is required to ensure safe assessment.', 5),
('e3000000-0000-0000-0000-000000000013', 'A', 'Section 3 (admission for treatment)', true, 'Correct. Section 3 allows compulsory admission for treatment for up to 6 months (renewable), and is appropriate when the diagnosis is established, a treatment plan is in place, and ongoing detention is required because the patient continues to lack capacity/insight and poses risk if discharged.', 1),
('e3000000-0000-0000-0000-000000000013', 'B', 'Extend Section 2 for a further 28 days', false, 'Ruled out because Section 2 cannot be renewed or extended; if ongoing detention is required beyond 28 days once diagnosis/treatment needs are clear, the patient must be moved to Section 3 (or discharged).', 2),
('e3000000-0000-0000-0000-000000000013', 'C', $x$Section 5(2) (doctor's holding power)$x$, false, 'Ruled out because Section 5(2) is a short-term holding power (up to 72 hours) for informal inpatients pending full assessment, not a mechanism for ongoing compulsory treatment of a known diagnosis.', 3),
('e3000000-0000-0000-0000-000000000013', 'D', 'Section 136', false, 'Ruled out because Section 136 relates to police removal of a person from a public place to a place of safety, and is not relevant to a patient already admitted and under psychiatric care.', 4),
('e3000000-0000-0000-0000-000000000013', 'E', 'Discharge her as she has already been in hospital for the maximum permitted time', false, $x$Ruled out because Section 2's 28-day limit does not represent a maximum permitted admission overall; escalation to Section 3 is appropriate when treatment needs continue and she remains at risk.$x$, 5),
('e3000000-0000-0000-0000-000000000014', 'A', 'Physically restrain him indefinitely without any legal framework', false, 'Ruled out because restraint without a legal basis is unlawful; Section 5(2) provides the appropriate short-term legal authority to prevent him leaving while an assessment is arranged.', 1),
('e3000000-0000-0000-0000-000000000014', 'B', 'Allow him to leave immediately as he was admitted voluntarily', false, 'Ruled out because there are significant concerns about his current risk; the law provides Section 5(2) precisely for this situation to allow safe assessment rather than immediate discharge against clinical advice.', 2),
('e3000000-0000-0000-0000-000000000014', 'C', $x$Use Section 5(2), the doctor's holding power, to detain him for up to 72 hours$x$, true, 'Correct. Section 5(2) allows a doctor in charge of the care of a voluntary inpatient (or their nominated deputy) to detain the patient for up to 72 hours to prevent them leaving, providing time to arrange a full Mental Health Act assessment (e.g. for Section 2 or 3).', 3),
('e3000000-0000-0000-0000-000000000014', 'D', 'Apply Section 3 directly without any assessment', false, 'Ruled out because Section 3 requires a formal Mental Health Act assessment by two doctors and an AMHP; it cannot be applied instantly without this process, hence the need for Section 5(2) to buy time.', 4),
('e3000000-0000-0000-0000-000000000014', 'E', 'Contact the police to arrest him under Section 136', false, 'Ruled out because Section 136 applies to removal of a person from a public place, not to a patient already an inpatient on a ward; Section 5(2) is the correct holding power in this context.', 5),
('e3000000-0000-0000-0000-000000000015', 'A', 'Arrest him for a public order offence', false, 'Ruled out because there is no clear criminal offence described; the priority is his safety and mental state, which Section 136 specifically addresses without requiring a criminal charge.', 1),
('e3000000-0000-0000-0000-000000000015', 'B', 'Section 2 of the Mental Health Act, applied directly by police officers', false, 'Ruled out because Section 2 requires two doctors and an AMHP and cannot be applied directly by police in the field; Section 136 is the correct immediate power for removal to a place of safety.', 2),
('e3000000-0000-0000-0000-000000000015', 'C', 'Take no action since he has not committed a crime', false, 'Ruled out because his presentation suggests acute mental disorder with immediate risk to his safety (wandering on a motorway bridge); Section 136 exists precisely to allow intervention in this situation.', 3),
('e3000000-0000-0000-0000-000000000015', 'D', $x$Section 5(2), the doctor's holding power$x$, false, 'Ruled out because Section 5(2) applies only to patients who are already voluntary inpatients in hospital, not to someone found in a public place by police.', 4),
('e3000000-0000-0000-0000-000000000015', 'E', 'Section 136 — remove him to a place of safety for a mental health assessment', true, 'Correct. Section 136 allows police to remove a person who appears to be suffering from a mental disorder and in need of care/control from a public place to a place of safety (typically a hospital-based suite) for a mental health assessment, for up to 24 hours (extendable by 12 hours).', 5),
('e3000000-0000-0000-0000-000000000016', 'A', 'Section 3 of the Mental Health Act', false, 'Ruled out because she does not require detention for treatment of a mental disorder under the Mental Health Act; her restriction relates to safe care for dementia-related risk, appropriately authorised via DoLS under the Mental Capacity Act.', 1),
('e3000000-0000-0000-0000-000000000016', 'B', 'Deprivation of Liberty Safeguards (DoLS) authorisation', true, 'Correct. Where a person lacking capacity is being cared for in a way that amounts to a deprivation of liberty (continuous supervision and control, and not free to leave) in a hospital or care home, this must be authorised under the Deprivation of Liberty Safeguards framework under the Mental Capacity Act, following an appropriate assessment process.', 2),
('e3000000-0000-0000-0000-000000000016', 'C', 'No authorisation is required as her family have agreed', false, 'Ruled out because family agreement alone does not provide the legal authority required; a formal DoLS assessment and authorisation process is required whenever a person lacking capacity is deprived of their liberty.', 3),
('e3000000-0000-0000-0000-000000000016', 'D', 'A Lasting Power of Attorney must be created retrospectively by the family', false, 'Ruled out because an LPA cannot be created retrospectively once a person lacks capacity to make one, and even a valid LPA would not itself authorise a deprivation of liberty without the DoLS process.', 4),
('e3000000-0000-0000-0000-000000000016', 'E', 'Section 136 of the Mental Health Act', false, 'Ruled out because Section 136 is a police power to remove someone from a public place, not relevant to authorising ongoing restrictive care in a care home.', 5),
('e3000000-0000-0000-0000-000000000017', 'A', 'Respect the valid and applicable advance decision to refuse treatment and do not ventilate him', true, 'Correct. A valid and applicable advance decision to refuse treatment (ADRT), made in writing (as required for decisions involving life-sustaining treatment), signed, and witnessed while the person had capacity, is legally binding and must be followed even if family disagree, provided it clearly applies to the current circumstances.', 1),
('e3000000-0000-0000-0000-000000000017', 'B', $x$Follow the family's wishes since he now lacks capacity$x$, false, 'Ruled out because a valid, applicable ADRT overrides family wishes; family members do not have authority to override a legally binding advance decision unless they hold a relevant, more recently executed Lasting Power of Attorney.', 2),
('e3000000-0000-0000-0000-000000000017', 'C', 'Proceed with ventilation because it is life-saving regardless of prior wishes', false, 'Ruled out because a valid ADRT specifically refusing this treatment, including in life-threatening circumstances, must be respected; the fact that treatment could be life-saving does not override a valid documented refusal.', 3),
('e3000000-0000-0000-0000-000000000017', 'D', 'Disregard the document because it was written before this specific illness episode', false, 'Ruled out because an ADRT remains valid and applicable if it clearly covers the specific treatment and circumstances now arising, regardless of exactly when it was written, provided it has not been withdrawn or superseded.', 4),
('e3000000-0000-0000-0000-000000000017', 'E', 'Refer the decision to the Court of Protection before any action is taken', false, 'Ruled out because a clearly valid and applicable ADRT does not require court involvement; court referral is reserved for genuine uncertainty or dispute about validity/applicability, which is not the primary issue described here.', 5),
('e3000000-0000-0000-0000-000000000018', 'A', 'Refuse to provide contraception and insist on informing her parents immediately', false, 'Ruled out because a Gillick-competent young person meeting the Fraser guideline criteria can consent to confidential contraceptive treatment; automatically breaching confidentiality to parents without her consent is not appropriate unless there are safeguarding concerns.', 1),
('e3000000-0000-0000-0000-000000000018', 'B', 'Refuse to see her at all until a parent accompanies her', false, 'Ruled out because minors can be assessed for Gillick competence and seen independently; there is no absolute requirement for parental attendance, particularly for sensitive sexual health consultations.', 2),
('e3000000-0000-0000-0000-000000000018', 'C', 'Assess her as Gillick competent and, if criteria are met, provide contraception confidentially without requiring parental involvement', true, 'Correct. If a young person under 16 demonstrates sufficient maturity and understanding to fully appreciate the nature, implications, and risks of the proposed treatment (Gillick competence), and the specific Fraser guidelines criteria for contraception are met (including that she is likely to have intercourse regardless, her best interests require contraceptive advice/treatment, and encouragement to involve parents where appropriate), she can consent to confidential contraception.', 3),
('e3000000-0000-0000-0000-000000000018', 'D', 'Provide contraception only with written parental consent regardless of her competence', false, $x$Ruled out because a competent young person's own valid consent is sufficient; parental consent is not a legal requirement when Gillick competence and Fraser criteria are satisfied.$x$, 4),
('e3000000-0000-0000-0000-000000000018', 'E', 'Report this as a safeguarding concern to social services without further assessment', false, 'Ruled out because a mutually consenting relationship between two young people of similar age, with no identified safeguarding concerns after appropriate assessment, does not automatically require a safeguarding referral; this would need clinical judgement based on the full context (e.g. significant age gap or coercion would raise concern, which is not present here).', 5),
('e3000000-0000-0000-0000-000000000019', 'A', 'Bulimia nervosa', false, 'Ruled out because bulimia nervosa is characterised by recurrent binge eating followed by compensatory behaviours (vomiting, laxative use) typically with a normal or near-normal body weight, not the severe underweight state described here.', 1),
('e3000000-0000-0000-0000-000000000019', 'B', 'Binge eating disorder', false, 'Ruled out because binge eating disorder involves recurrent episodes of binge eating without compensatory behaviours, typically associated with normal or elevated weight, not severe restriction and being underweight.', 2),
('e3000000-0000-0000-0000-000000000019', 'C', 'Major depressive disorder with poor appetite', false, 'Ruled out because although depression can cause reduced appetite and weight loss, the described intense fear of weight gain and body image disturbance are specific to an eating disorder, not simply low mood.', 3),
('e3000000-0000-0000-0000-000000000019', 'D', 'Anorexia nervosa', true, $x$Correct. Persistent restriction of energy intake leading to significantly low body weight, intense fear of weight gain, and a disturbance in body image/self-perception (believing she is 'too fat' despite being underweight) are the core diagnostic features of anorexia nervosa.$x$, 4),
('e3000000-0000-0000-0000-000000000019', 'E', 'Hyperthyroidism', false, 'Ruled out because while hyperthyroidism can cause weight loss, it does not explain the deliberate food restriction, fear of weight gain, and distorted body image; these features and the clinical picture are more consistent with anorexia nervosa (though thyroid function should still be checked to exclude comorbid or alternative organic causes).', 5),
('e3000000-0000-0000-0000-000000000020', 'A', 'Diabetic ketoacidosis', false, 'Ruled out because there is no reported hyperglycaemia, ketosis, or acidosis; the electrolyte pattern (low phosphate, potassium, magnesium in the context of recent refeeding) is characteristic of refeeding syndrome, not DKA.', 1),
('e3000000-0000-0000-0000-000000000020', 'B', $x$Wernicke's encephalopathy$x$, false, $x$Ruled out because although also a risk in malnutrition, Wernicke's classically presents with ataxia, confusion, and ophthalmoplegia due to thiamine deficiency, not this specific electrolyte derangement pattern; it should still be considered/prevented alongside refeeding risk but the biochemistry here points to refeeding syndrome.$x$, 2),
('e3000000-0000-0000-0000-000000000020', 'C', 'Acute kidney injury', false, 'Ruled out because there is no mention of deranged renal function (urea/creatinine) or oliguria; the clinical and biochemical picture (hypophosphataemia, hypokalaemia, hypomagnesaemia after starting feeding) fits refeeding syndrome.', 3),
('e3000000-0000-0000-0000-000000000020', 'D', 'Normal expected response to refeeding requiring no action', false, 'Ruled out because these electrolyte derangements are dangerous and require urgent correction and slowing of feeding rate; refeeding syndrome can be fatal (cardiac arrhythmia, heart failure) if unrecognised.', 4),
('e3000000-0000-0000-0000-000000000020', 'E', 'Refeeding syndrome', true, 'Correct. Refeeding syndrome occurs when nutrition is reintroduced too quickly after prolonged starvation, causing an insulin surge that drives phosphate, potassium, and magnesium intracellularly, resulting in severe hypophosphataemia (as seen here), hypokalaemia, and hypomagnesaemia, with associated confusion, oedema, and risk of cardiac arrhythmia and cardiac failure.', 5),
('e3000000-0000-0000-0000-000000000021', 'A', 'Continue routine outpatient follow-up in 4 weeks', false, 'Ruled out because these findings indicate acute, potentially life-threatening cardiac risk; routine outpatient follow-up is unsafe and delays necessary urgent medical assessment.', 1),
('e3000000-0000-0000-0000-000000000021', 'B', 'Reassure her that bradycardia is a normal, benign adaptation to starvation requiring no action', false, 'Ruled out because although bradycardia is common in anorexia nervosa, this degree combined with QTc prolongation and hypokalaemia significantly raises arrhythmia risk and needs urgent assessment, not reassurance alone.', 2),
('e3000000-0000-0000-0000-000000000021', 'C', 'Commence an oral beta-blocker to manage her symptoms', false, 'Ruled out because beta-blockers would worsen bradycardia and are not appropriate; the priority is urgent medical admission to address the underlying nutritional/electrolyte cause.', 3),
('e3000000-0000-0000-0000-000000000021', 'D', 'Arrange outpatient 24-hour Holter monitoring over the next week', false, 'Ruled out because the current findings already indicate significant acute risk requiring immediate inpatient assessment; deferring monitoring by a week is unsafe.', 4),
('e3000000-0000-0000-0000-000000000021', 'E', 'Urgent same-day medical admission for cardiac monitoring and correction of hypokalaemia', true, 'Correct. Marked bradycardia (HR 42) with QTc prolongation (470 ms) and hypokalaemia in the context of severe anorexia nervosa indicates significant cardiac risk (risk of malignant arrhythmia and sudden cardiac death) and requires urgent same-day medical admission for cardiac monitoring and careful electrolyte correction, rather than continued outpatient management.', 5),
('e3000000-0000-0000-0000-000000000022', 'A', 'Anorexia nervosa, binge-purge subtype', false, 'Ruled out because anorexia nervosa requires a significantly low body weight; her BMI of 23 kg/m2 is within the normal range, which is inconsistent with anorexia nervosa.', 1),
('e3000000-0000-0000-0000-000000000022', 'B', 'Bulimia nervosa', true, 'Correct. Recurrent episodes of binge eating with a subjective loss of control, followed by recurrent inappropriate compensatory behaviours (self-induced vomiting, laxative misuse) to prevent weight gain, occurring at least weekly for several months, in a patient with a near-normal BMI, is characteristic of bulimia nervosa.', 2),
('e3000000-0000-0000-0000-000000000022', 'C', 'Binge eating disorder', false, 'Ruled out because binge eating disorder does not involve recurrent inappropriate compensatory behaviours such as vomiting or laxative misuse, which are present here.', 3),
('e3000000-0000-0000-0000-000000000022', 'D', 'Pica', false, 'Ruled out because pica involves persistent eating of non-nutritive, non-food substances, which is not described in this case.', 4),
('e3000000-0000-0000-0000-000000000022', 'E', 'Rumination disorder', false, 'Ruled out because rumination disorder involves repeated regurgitation of previously swallowed food that is re-chewed, re-swallowed, or spat out, distinct from the binge-purge cycle described here.', 5),
('e3000000-0000-0000-0000-000000000023', 'A', 'Binge eating disorder', true, 'Correct. Recurrent binge eating episodes with a sense of loss of control, rapid eating, eating until uncomfortably full, eating alone due to embarrassment, and marked distress, occurring at least weekly for 3 months, without recurrent compensatory behaviours, is characteristic of binge eating disorder; it is commonly associated with obesity.', 1),
('e3000000-0000-0000-0000-000000000023', 'B', 'Bulimia nervosa', false, 'Ruled out because bulimia nervosa requires recurrent inappropriate compensatory behaviours (vomiting, laxatives, excessive exercise) following binges, which are explicitly absent in this case.', 2),
('e3000000-0000-0000-0000-000000000023', 'C', 'Anorexia nervosa', false, 'Ruled out because anorexia nervosa requires significantly low body weight from restriction, which is inconsistent with a BMI of 34 kg/m2 and a history of binge eating rather than restriction.', 3),
('e3000000-0000-0000-0000-000000000023', 'D', 'Night eating syndrome', false, 'Ruled out because night eating syndrome specifically involves recurrent episodes of eating after awakening from sleep or excessive food intake after the evening meal, which is not described here.', 4),
('e3000000-0000-0000-0000-000000000023', 'E', 'Normal overeating requiring no diagnosis or intervention', false, 'Ruled out because the recurrent loss of control, associated distress, and frequency/duration criteria are met for a formal binge eating disorder diagnosis, which benefits from active psychological treatment.', 5),
('e3000000-0000-0000-0000-000000000024', 'A', 'Respect her refusal and continue outpatient community eating disorder follow-up only', false, 'Ruled out because her presentation indicates acute, severe physical risk (marked bradycardia, syncope, rapid weight loss) that cannot be safely managed as an outpatient; refusal in this context requires careful capacity assessment rather than simple acceptance.', 1),
('e3000000-0000-0000-0000-000000000024', 'B', 'Discharge with dietary advice leaflets and review in 6 weeks', false, 'Ruled out because this significantly underestimates the acuity of her presentation, which meets high-risk criteria requiring same-day assessment, not a routine, delayed review.', 2),
('e3000000-0000-0000-0000-000000000024', 'C', 'Commence oral iron supplementation and reassess in 2 weeks', false, 'Ruled out because this does not address the acute cardiovascular risk from severe bradycardia, postural hypotension, and syncope, which requires urgent medical assessment, not iron supplementation.', 3),
('e3000000-0000-0000-0000-000000000024', 'D', 'Arrange urgent same-day medical assessment and likely admission given her physical risk, involving the Mental Health Act or Mental Capacity Act if she continues to refuse and lacks capacity', true, 'Correct. Severe bradycardia, postural hypotension, syncope, rapid weight loss, and very low BMI in this adolescent indicate high medical risk (per MARSIPAN/junior MARSIPAN risk criteria) requiring urgent same-day medical admission; if she lacks capacity to weigh the risks of refusing life-saving treatment (which can occur with severe malnutrition/cognitive impact), the Mental Health Act or Mental Capacity Act (including parental consent considerations for a minor) may need to be used to ensure safe treatment.', 4),
('e3000000-0000-0000-0000-000000000024', 'E', 'Refer only to child and adolescent mental health services (CAMHS) for psychological therapy with no medical input', false, 'Ruled out because her acute physical risk requires urgent medical (paediatric/general medical) assessment and stabilisation alongside eating disorder psychiatric input, not psychological therapy alone.', 5),
('e3000000-0000-0000-0000-000000000025', 'A', 'Primary hyperparathyroidism unrelated to her eating disorder', false, 'Ruled out because there is no evidence provided of hypercalcaemia or elevated parathyroid hormone; the clinical context (long-standing anorexia nervosa with prolonged amenorrhoea) points to a malnutrition/oestrogen-deficiency mechanism rather than primary hyperparathyroidism.', 1),
('e3000000-0000-0000-0000-000000000025', 'B', 'Normal age-related bone density change requiring no further action', false, 'Ruled out because a T-score of -2.7 in a 26-year-old is markedly abnormal and diagnostic of osteoporosis; this is not a normal age-related finding and requires active management.', 2),
('e3000000-0000-0000-0000-000000000025', 'C', 'Osteoporosis secondary to prolonged hypothalamic-pituitary-gonadal axis suppression and oestrogen deficiency from chronic anorexia nervosa', true, 'Correct. Prolonged low body weight and malnutrition in anorexia nervosa suppress the hypothalamic-pituitary-gonadal axis, causing amenorrhoea and oestrogen deficiency, which along with malnutrition-related effects on bone metabolism (reduced IGF-1, cortisol excess) leads to reduced bone mineral density and osteoporosis; this is a well-recognised long-term complication of chronic anorexia nervosa.', 3),
('e3000000-0000-0000-0000-000000000025', 'D', 'Vitamin D toxicity', false, 'Ruled out because vitamin D toxicity causes hypercalcaemia, not reduced bone density; there is no supporting evidence for this in the vignette, and the clinical picture fits chronic malnutrition-related bone loss.', 4),
('e3000000-0000-0000-0000-000000000025', 'E', 'Corticosteroid-induced osteoporosis from long-term steroid treatment', false, 'Ruled out because there is no history of corticosteroid use provided; the relevant risk factors here are chronic anorexia nervosa and prolonged amenorrhoea/oestrogen deficiency.', 5),
('e3000000-0000-0000-0000-000000000026', 'A', 'Detention and treatment under the Mental Health Act, as anorexia nervosa is a mental disorder requiring treatment that may include compulsory feeding', true, 'Correct. Where a patient with anorexia nervosa lacks capacity due to the effects of the illness and refuses life-saving nutrition, and treatment of the eating disorder (including feeding) is necessary for her health/safety, detention and treatment under the Mental Health Act is the appropriate legal route, as feeding is considered treatment for the underlying mental disorder.', 1),
('e3000000-0000-0000-0000-000000000026', 'B', 'No treatment can be given as she is an adult who has refused', false, 'Ruled out because her refusal is not a valid, capacitous refusal — she lacks capacity due to the cognitive effects of severe starvation, and without a valid ADRT, life-saving treatment can and should be provided under an appropriate legal framework.', 2),
('e3000000-0000-0000-0000-000000000026', 'C', 'Only the Mental Capacity Act can be used, as the Mental Health Act does not apply to eating disorders', false, 'Ruled out because anorexia nervosa is recognised as a mental disorder under the Mental Health Act, and compulsory feeding as treatment for anorexia nervosa is an established use of the Mental Health Act when criteria for detention are met.', 3),
('e3000000-0000-0000-0000-000000000026', 'D', 'Obtain consent from her parents as she is unable to consent herself', false, 'Ruled out because she is an adult, and parents/relatives do not have legal authority to consent to treatment on behalf of an adult who lacks capacity in England and Wales; a formal legal framework (Mental Health Act, or the Mental Capacity Act if MHA criteria are not met) is required.', 4),
('e3000000-0000-0000-0000-000000000026', 'E', 'Wait until she regains capacity naturally before any treatment is given', false, 'Ruled out because she is at imminent risk of death from malnutrition; delaying treatment until capacity spontaneously returns (which is unlikely to occur without nutritional treatment) would place her at unacceptable risk of harm or death.', 5),
('e3000000-0000-0000-0000-000000000027', 'A', 'Immediate psychiatric hospital admission', false, 'Ruled out because there is no indication of risk to himself or others, psychotic symptoms, or inability to manage safely at home; this presentation can be managed in primary care.', 1),
('e3000000-0000-0000-0000-000000000027', 'B', 'An SSRI (e.g. sertraline) combined with a structured psychological intervention such as CBT', true, 'Correct. For moderate depression with clear functional impact, NICE recommends combined treatment with an antidepressant (SSRI first-line) and a high-intensity psychological intervention such as CBT, which is more effective than either alone.', 2),
('e3000000-0000-0000-0000-000000000027', 'C', 'Benzodiazepines as sole long-term treatment', false, 'Ruled out because benzodiazepines are not indicated for depression and carry dependence risk without addressing the underlying mood disorder.', 3),
('e3000000-0000-0000-0000-000000000027', 'D', 'Watchful waiting with no active treatment for 3 months', false, 'Ruled out because his symptoms are of moderate severity with significant functional impact (weight loss, anhedonia, low energy) over 6 weeks, warranting active treatment rather than watchful waiting (which is reserved for mild, self-limiting presentations).', 4),
('e3000000-0000-0000-0000-000000000027', 'E', 'Electroconvulsive therapy', false, 'Ruled out because ECT is reserved for severe, treatment-resistant depression, depression with psychotic features, or situations requiring rapid response (e.g. catatonia, high suicide risk with refusal to eat/drink), not first-line for this presentation.', 5),
('e3000000-0000-0000-0000-000000000028', 'A', 'Start an SSRI antidepressant immediately', false, 'Ruled out because antidepressants can precipitate or worsen mania in bipolar disorder and are not appropriate first-line treatment for an acute manic episode.', 1),
('e3000000-0000-0000-0000-000000000028', 'B', 'Reassure her and arrange routine outpatient follow-up in 6 weeks', false, 'Ruled out because acute mania with impulsive/risky behaviour (excessive spending, grandiosity, lack of insight) requires urgent assessment and treatment, not delayed routine follow-up.', 2),
('e3000000-0000-0000-0000-000000000028', 'C', 'Urgent psychiatric assessment and initiation of an oral antipsychotic (e.g. olanzapine or risperidone)', true, 'Correct. This presentation is consistent with an acute manic episode (elevated/irritable mood, decreased need for sleep, grandiosity, pressured speech, distractibility, impulsive/risky behaviour) requiring urgent psychiatric assessment; first-line acute treatment is an oral antipsychotic, with consideration of admission if risk (financial, social, safety) is high.', 3),
('e3000000-0000-0000-0000-000000000028', 'D', 'Commence lithium as the immediate acute treatment', false, 'Ruled out because lithium takes days to weeks to reach therapeutic effect and requires careful dose titration with monitoring; it is not suitable for rapid acute control of mania, for which an antipsychotic is preferred initially.', 4),
('e3000000-0000-0000-0000-000000000028', 'E', 'Discharge home with advice to restart her previous medication in her own time', false, 'Ruled out because she currently lacks insight into her risk-taking behaviour and requires urgent professional assessment and treatment initiation, not simply being advised to self-manage.', 5),
('e3000000-0000-0000-0000-000000000029', 'A', 'Increase the lithium dose because her level is within the therapeutic range', false, 'Ruled out because her new symptoms suggest toxicity may be developing due to the NSAID interaction reducing lithium clearance; increasing the dose in this context would be dangerous.', 1),
('e3000000-0000-0000-0000-000000000029', 'B', 'Continue the ibuprofen and lithium unchanged, as the lithium level was therapeutic 2 weeks ago', false, 'Ruled out because the NSAID interaction can cause lithium levels to rise significantly even after a previously therapeutic result; her new symptoms require urgent reassessment, not reassurance based on an outdated level.', 2),
('e3000000-0000-0000-0000-000000000029', 'C', 'Stop lithium permanently and switch to sodium valproate immediately without further assessment', false, 'Ruled out because the priority is first to identify and remove the precipitant (NSAID) and assess for toxicity; abrupt discontinuation of a long-term stable mood stabiliser without proper evaluation is not the most appropriate immediate step.', 3),
('e3000000-0000-0000-0000-000000000029', 'D', 'Stop the ibuprofen and check a repeat serum lithium level urgently', true, 'Correct. NSAIDs reduce renal lithium clearance and can precipitate lithium toxicity even when a previous level was within the therapeutic range; new tremor, nausea, and diarrhoea in this context are concerning for toxicity, and the NSAID should be stopped immediately with urgent repeat lithium level and renal function testing.', 4),
('e3000000-0000-0000-0000-000000000029', 'E', 'Advise her to take the ibuprofen with food and continue as normal', false, 'Ruled out because this does not address the significant risk of the NSAID-lithium interaction precipitating toxicity; the interaction itself, not gastric tolerance, is the concern.', 5),
('e3000000-0000-0000-0000-000000000030', 'A', $x$Reassure her that this is normal 'baby blues' and review in 2 weeks$x$, false, 'Ruled out because baby blues is a mild, transient, self-limiting low mood/tearfulness in the first few days postpartum without psychotic symptoms; this presentation with psychosis and risk to the baby is a psychiatric emergency, not baby blues.', 1),
('e3000000-0000-0000-0000-000000000030', 'B', 'Start an SSRI in the community and review in 1 week', false, 'Ruled out because this presentation requires urgent same-day assessment and likely admission due to the risk posed by active psychosis with a plan involving the infant; outpatient antidepressant treatment with delayed review is unsafe.', 2),
('e3000000-0000-0000-0000-000000000030', 'C', 'Discharge home with health visitor follow-up only', false, 'Ruled out because this significantly underestimates the acuity and risk of postpartum psychosis, which requires urgent psychiatric assessment and likely admission, not routine community follow-up alone.', 3),
('e3000000-0000-0000-0000-000000000030', 'D', 'Arrange routine outpatient psychiatric referral within 4 weeks', false, 'Ruled out because the level of risk described (psychosis, agitation, and a stated plan involving the baby) requires same-day, not routine, assessment.', 4),
('e3000000-0000-0000-0000-000000000030', 'E', 'Urgent same-day psychiatric assessment with a view to admission, ideally to a specialist mother and baby unit', true, 'Correct. This presentation (rapid onset within 2 weeks postpartum, psychotic symptoms including delusions and hallucinations relating to the baby, agitation, and a stated plan involving the baby) is postpartum psychosis, a psychiatric emergency with risk of harm to mother and infant, requiring same-day urgent psychiatric assessment and usually admission, ideally to a specialist mother and baby unit where mother-infant bonding can be supported alongside treatment.', 5),
('e3000000-0000-0000-0000-000000000031', 'A', 'Start an SSRI and arrange review with the crisis team in 48 hours', false, 'Ruled out because antidepressant treatment takes weeks to have effect and does not address the immediate, severe risk of suicide today; urgent admission is required rather than a delayed community review.', 1),
('e3000000-0000-0000-0000-000000000031', 'B', 'Urgent psychiatric admission, using the Mental Health Act if he does not consent, given active suicidal intent and psychotic depression', true, 'Correct. This is severe depression with psychotic features (nihilistic delusion that his organs are rotting) and an active, specific suicide plan with stated intent to act today; this constitutes a psychiatric emergency requiring urgent admission for safety and treatment, using the Mental Health Act for compulsory admission if he refuses and detention criteria are met.', 2),
('e3000000-0000-0000-0000-000000000031', 'C', 'Refer for outpatient CBT as first-line treatment', false, 'Ruled out because outpatient psychological therapy is entirely inappropriate for a patient with active suicidal intent, a specific plan, and psychotic depression requiring urgent inpatient care.', 3),
('e3000000-0000-0000-0000-000000000031', 'D', 'Reassure him that his beliefs about his organs are understandable given how he feels, with no further action', false, 'Ruled out because this fails to recognise a fixed, false, psychotic belief (nihilistic delusion) and does not address the acute, severe suicide risk requiring urgent intervention.', 4),
('e3000000-0000-0000-0000-000000000031', 'E', 'Discharge with safety planning and follow-up with his GP in 2 weeks', false, 'Ruled out because the severity of risk (active plan, intent to act today, psychotic symptoms) makes discharge unsafe; urgent admission is required.', 5),
('e3000000-0000-0000-0000-000000000032', 'A', 'Immediate detention under the Mental Health Act', false, 'Ruled out because there is no evidence of a specific plan, intent, or means, and she has protective factors and engages with care; compulsory detention is disproportionate and not indicated at this level of risk.', 1),
('e3000000-0000-0000-0000-000000000032', 'B', 'No further action is needed as she denies a specific plan', false, 'Ruled out because passive suicidal ideation still requires structured assessment, follow-up, and safety-netting; simply dismissing the concern without any plan is unsafe.', 2),
('e3000000-0000-0000-0000-000000000032', 'C', 'Structured risk assessment covering intent, plan, means, protective factors, and safety-netting with a clear follow-up and crisis line information', true, 'Correct. A thorough risk assessment considers ideation, intent, plan, access to means, and protective factors (social support, no prior attempts, engagement with services); when risk appears currently low but present, appropriate safety-netting includes clear follow-up arrangements, crisis contact information, and involving support networks, rather than either dismissing the risk or over-escalating to admission.', 3),
('e3000000-0000-0000-0000-000000000032', 'D', 'Advise her partner to remove her from all social contact to keep her safe', false, 'Ruled out because social isolation is a risk factor for worsening mood and suicide risk, not a protective measure; maintaining supportive social contact is protective.', 4),
('e3000000-0000-0000-0000-000000000032', 'E', 'Prescribe a large supply (3 months) of antidepressant medication to start immediately', false, 'Ruled out because prescribing a large quantity of medication to a patient with any suicidal ideation risks provision of a means of overdose; smaller, more frequent prescriptions with closer follow-up are safer practice.', 5),
('e3000000-0000-0000-0000-000000000033', 'A', 'Neuroleptic malignant syndrome', false, 'Ruled out because NMS is associated with antipsychotic use (or dopamine antagonist withdrawal) and classically presents with lead-pipe rigidity and hyporeflexia, not the hyperreflexia and clonus seen here, and there is no antipsychotic use in this history.', 1),
('e3000000-0000-0000-0000-000000000033', 'B', 'Opioid withdrawal', false, 'Ruled out because she has recently started, not stopped, tramadol; opioid withdrawal does not typically cause hyperreflexia and clonus, which point instead to serotonin excess.', 2),
('e3000000-0000-0000-0000-000000000033', 'C', 'Sepsis of unknown source', false, 'Ruled out because although fever is present, the specific combination of neuromuscular signs (hyperreflexia, clonus) with a clear precipitant (recent addition of a second serotonergic drug) strongly points to serotonin syndrome rather than an infective process.', 3),
('e3000000-0000-0000-0000-000000000033', 'D', 'Anticholinergic toxicity', false, 'Ruled out because anticholinergic toxicity typically causes dry skin, mydriasis, urinary retention, and reduced bowel sounds/constipation, whereas this patient has diaphoresis (sweating) and diarrhoea, and hyperreflexia/clonus which fit serotonin syndrome rather than an anticholinergic picture.', 4),
('e3000000-0000-0000-0000-000000000033', 'E', 'Serotonin syndrome', true, 'Correct. The combination of an SSRI (sertraline) and tramadol (which also has serotonergic activity) increases serotonin syndrome risk; the triad of altered mental state/agitation, autonomic instability (fever, sweating, diarrhoea), and neuromuscular abnormalities (hyperreflexia, clonus) is classic for serotonin syndrome.', 5),
('e3000000-0000-0000-0000-000000000034', 'A', 'Relapse of her underlying depression', false, 'Ruled out because the rapid onset (within days of stopping) and the specific symptom pattern (electric shock sensations, dizziness) are characteristic of discontinuation syndrome rather than a depressive relapse, which typically develops more gradually over weeks.', 1),
('e3000000-0000-0000-0000-000000000034', 'B', 'Serotonin syndrome', false, 'Ruled out because serotonin syndrome results from excess serotonergic activity (usually from combining serotonergic drugs) and presents with hyperthermia, neuromuscular abnormalities (clonus, hyperreflexia), and autonomic instability, not from abrupt cessation of a single agent.', 2),
('e3000000-0000-0000-0000-000000000034', 'C', 'New-onset vestibular neuritis', false, 'Ruled out because the temporal relationship to abrupt SSRI cessation and the characteristic constellation of symptoms (not isolated vertigo) point clearly to a discontinuation syndrome rather than a primary vestibular disorder.', 3),
('e3000000-0000-0000-0000-000000000034', 'D', 'Antidepressant discontinuation syndrome', true, $x$Correct. Abrupt cessation of an SSRI, particularly one with a shorter half-life such as paroxetine, commonly causes a discontinuation syndrome within days, with symptoms including dizziness, 'electric shock' sensations (paraesthesia), nausea, anxiety, and sleep disturbance/vivid dreams.$x$, 4),
('e3000000-0000-0000-0000-000000000034', 'E', 'Normal anxiety unrelated to medication changes', false, 'Ruled out because the specific symptom cluster and clear temporal link to abruptly stopping paroxetine strongly indicate a pharmacological discontinuation effect rather than coincidental anxiety.', 5),
('e3000000-0000-0000-0000-000000000035', 'A', 'Urgent referral to an early intervention in psychosis (EIP) service', true, 'Correct. This presentation of first-episode psychosis (auditory hallucinations discussing him in the third person, and a bizarre persecutory/somatic delusion) in a young person warrants urgent referral to a specialist early intervention in psychosis service, which improves long-term outcomes through prompt, comprehensive assessment and treatment.', 1),
('e3000000-0000-0000-0000-000000000035', 'B', 'Reassurance that this is normal exam stress and review in 3 months', false, 'Ruled out because these are clear psychotic symptoms (hallucinations and delusions) with functional decline, not simple stress, and require urgent specialist assessment, not reassurance and delay.', 2),
('e3000000-0000-0000-0000-000000000035', 'C', 'Commence long-term benzodiazepines as sole treatment in primary care', false, 'Ruled out because benzodiazepines do not treat psychosis and this presentation requires specialist psychiatric assessment and likely antipsychotic treatment, not primary care benzodiazepine prescribing.', 3),
('e3000000-0000-0000-0000-000000000035', 'D', 'Advise him to reduce his workload and reassess in 6 months with no referral', false, 'Ruled out because first-episode psychosis requires prompt specialist assessment; delaying treatment worsens prognosis, and lifestyle advice alone is inadequate for active psychotic symptoms.', 4),
('e3000000-0000-0000-0000-000000000035', 'E', 'Refer directly for detention under the Mental Health Act without further assessment', false, 'Ruled out because there is no described immediate risk to himself or others that necessitates compulsory detention; the appropriate next step is urgent specialist assessment via early intervention services, with detention considered only if risk and detention criteria are subsequently identified.', 5),
('e3000000-0000-0000-0000-000000000036', 'A', 'Thought insertion', false, $x$Ruled out because thought insertion refers to the belief that thoughts are being placed into one's mind by an external force, not that one's own thoughts are being transmitted outward to others.$x$, 1),
('e3000000-0000-0000-0000-000000000036', 'B', 'Thought withdrawal', false, $x$Ruled out because thought withdrawal is the belief that thoughts are being removed or extracted from one's mind by an external agency, distinct from the broadcasting of one's own thoughts.$x$, 2),
('e3000000-0000-0000-0000-000000000036', 'C', 'Somatic passivity', false, $x$Ruled out because somatic passivity refers to the belief that one's bodily sensations are being controlled or imposed by an external force, not related to thoughts being heard by others.$x$, 3),
('e3000000-0000-0000-0000-000000000036', 'D', 'Thought broadcasting', true, $x$Correct. The belief that one's thoughts are being transmitted or broadcast so that others can perceive them, even without speaking, is termed thought broadcasting, a classic first-rank symptom of schizophrenia.$x$, 4),
('e3000000-0000-0000-0000-000000000036', 'E', 'Running commentary (a separate symptom also present here)', false, 'Ruled out as the answer to this specific question because although the running commentary voice is also described in the vignette, the specific phenomenon of thoughts being audible/perceived by others as described is thought broadcasting, not running commentary.', 5),
('e3000000-0000-0000-0000-000000000037', 'A', 'Stop all antipsychotic treatment permanently with no substitute', false, 'Ruled out because while the causative dose may need review, abruptly stopping all antipsychotic treatment is not the immediate priority; the acute dystonic reaction itself needs prompt anticholinergic treatment, and ongoing psychosis still requires management, potentially with dose adjustment or a different agent.', 1),
('e3000000-0000-0000-0000-000000000037', 'B', 'Increase the dose of haloperidol to overcome the reaction', false, 'Ruled out because increasing the causative drug would worsen the dystonic reaction; the correct approach is anticholinergic treatment, not increasing the antipsychotic dose.', 2),
('e3000000-0000-0000-0000-000000000037', 'C', 'Intramuscular or intravenous procyclidine', true, 'Correct. This presentation (torticollis, oculogyric crisis) shortly after starting a typical antipsychotic is acute dystonia, an extrapyramidal side effect; it is treated promptly with an anticholinergic such as procyclidine, which provides rapid symptomatic relief.', 3),
('e3000000-0000-0000-0000-000000000037', 'D', 'Intravenous lorazepam as the definitive treatment', false, 'Ruled out because although benzodiazepines can provide some symptomatic relief, the specific and most effective treatment for acute dystonia is an anticholinergic agent such as procyclidine, not a benzodiazepine.', 4),
('e3000000-0000-0000-0000-000000000037', 'E', 'Reassurance only, as this will resolve spontaneously within 24 hours without treatment', false, 'Ruled out because acute dystonia is distressing, potentially dangerous (e.g. laryngeal dystonia can compromise the airway), and responds rapidly to anticholinergic treatment, so active treatment should not be withheld.', 5),
('e3000000-0000-0000-0000-000000000038', 'A', 'Neuroleptic malignant syndrome', true, 'Correct. The combination of fever, lead-pipe muscle rigidity, autonomic instability (tachycardia, labile blood pressure, sweating), altered mental state, and markedly elevated creatine kinase in a patient on an antipsychotic is characteristic of neuroleptic malignant syndrome, a rare but life-threatening emergency.', 1),
('e3000000-0000-0000-0000-000000000038', 'B', 'Serotonin syndrome', false, 'Ruled out because serotonin syndrome is typically associated with serotonergic drugs (SSRIs, tramadol) and presents with hyperreflexia and clonus rather than the lead-pipe rigidity and hyporeflexia seen in NMS, and there is no serotonergic drug history here.', 2),
('e3000000-0000-0000-0000-000000000038', 'C', 'Acute dystonia', false, 'Ruled out because acute dystonia causes localised abnormal muscle contraction (e.g. torticollis, oculogyric crisis) rather than generalised rigidity with fever, autonomic instability, and markedly elevated CK.', 3),
('e3000000-0000-0000-0000-000000000038', 'D', 'Sepsis from an unidentified source', false, 'Ruled out because although fever and leucocytosis could suggest infection, the combination of lead-pipe rigidity, autonomic instability, and markedly elevated CK in a patient on long-term antipsychotic treatment is much more consistent with neuroleptic malignant syndrome; infection should still be considered/excluded as part of the workup, but NMS is the most likely diagnosis here.', 4),
('e3000000-0000-0000-0000-000000000038', 'E', 'Malignant hyperthermia', false, 'Ruled out because malignant hyperthermia is triggered by volatile anaesthetic agents or suxamethonium during anaesthesia, not by chronic antipsychotic use, making this diagnosis inconsistent with the clinical context given.', 5),
('e3000000-0000-0000-0000-000000000039', 'A', 'Continue clozapine and simply repeat the full blood count in 4 weeks', false, 'Ruled out because a significantly reduced neutrophil count on clozapine is a serious safety signal requiring immediate cessation of the drug, not continued treatment with delayed repeat testing.', 1),
('e3000000-0000-0000-0000-000000000039', 'B', 'Stop clozapine immediately and refer urgently for haematology assessment', true, 'Correct. Clozapine carries a risk of life-threatening agranulocytosis/neutropenia, which is why mandatory regular full blood count monitoring is required; a significantly reduced neutrophil count requires immediate cessation of clozapine and urgent haematology assessment to manage the risk of severe infection.', 2),
('e3000000-0000-0000-0000-000000000039', 'C', 'Increase the clozapine dose to assess for a dose-dependent effect', false, 'Ruled out because increasing the dose of a drug causing neutropenia would worsen the risk of agranulocytosis and severe infection; the drug must be stopped, not increased.', 3),
('e3000000-0000-0000-0000-000000000039', 'D', 'Switch directly to another antipsychotic without addressing the current blood result', false, 'Ruled out because the immediate priority is safely managing the neutropenia (stopping clozapine, urgent haematology input, monitoring for infection) before considering longer-term alternative antipsychotic strategy.', 4),
('e3000000-0000-0000-0000-000000000039', 'E', 'Reassure her that mild fluctuations in blood count are expected and no action is needed', false, 'Ruled out because this degree of neutropenia on clozapine is a recognised serious adverse effect requiring urgent action, not reassurance, given the risk of progression to agranulocytosis and life-threatening infection.', 5),
('e3000000-0000-0000-0000-000000000040', 'A', 'No action is needed as this is an unavoidable and untreatable consequence of antipsychotic treatment', false, 'Ruled out because although some metabolic risk is expected with certain antipsychotics, active monitoring and management (lifestyle change, medication review, treating dysglycaemia/dyslipidaemia) are essential and effective, not something to be ignored.', 1),
('e3000000-0000-0000-0000-000000000040', 'B', 'Stop the antipsychotic abruptly with no monitoring or replacement plan', false, 'Ruled out because abrupt cessation of antipsychotic treatment risks relapse of schizophrenia; any medication change should be planned and gradual, alongside addressing the metabolic findings, not abrupt discontinuation.', 2),
('e3000000-0000-0000-0000-000000000040', 'C', 'Refer for immediate bariatric surgery as the first-line intervention', false, 'Ruled out because bariatric surgery is not a first-line intervention for antipsychotic-associated weight gain; lifestyle measures, medication review, and medical management of metabolic risk factors are appropriate initial steps.', 3),
('e3000000-0000-0000-0000-000000000040', 'D', 'Increase the olanzapine dose since he denies any physical symptoms', false, 'Ruled out because increasing the dose of a drug already causing significant metabolic side effects would likely worsen these problems and is not indicated by the absence of subjective symptoms.', 4),
('e3000000-0000-0000-0000-000000000040', 'E', 'Address the emerging metabolic syndrome with lifestyle intervention, consider a medication review (e.g. switching to a lower metabolic-risk antipsychotic), and manage cardiovascular risk factors', true, 'Correct. Olanzapine carries a high risk of weight gain, dyslipidaemia, and impaired glucose tolerance/diabetes; annual physical health monitoring in patients on antipsychotics is essential to detect this, and management involves lifestyle intervention, considering switching to an antipsychotic with lower metabolic risk if clinically appropriate, and managing cardiovascular/diabetes risk factors directly.', 5),
('e3000000-0000-0000-0000-000000000041', 'A', 'Immediate physical restraint with no medication as the definitive intervention', false, 'Ruled out because prolonged physical restraint alone carries significant risks (positional asphyxia, injury) and is not a sustainable definitive intervention; rapid tranquillisation alongside safe, minimal restraint is the recommended approach when de-escalation fails.', 1),
('e3000000-0000-0000-0000-000000000041', 'B', 'Discharge him back to the street once he calms down temporarily', false, 'Ruled out because ongoing psychosis with aggression and risk requires further assessment and likely admission, not discharge, even if he calms briefly.', 2),
('e3000000-0000-0000-0000-000000000041', 'C', 'Oral antipsychotic medication only, declined by the patient', false, 'Ruled out because he is refusing oral treatment and remains an immediate danger; when a patient cannot be safely managed with oral medication, parenteral rapid tranquillisation is required.', 3),
('e3000000-0000-0000-0000-000000000041', 'D', 'Wait without any intervention until he tires himself out', false, 'Ruled out because this exposes staff, the patient, and others to ongoing risk of harm; active intervention (de-escalation followed by rapid tranquillisation if needed) is required for safety.', 4),
('e3000000-0000-0000-0000-000000000041', 'E', 'Rapid tranquillisation with an intramuscular antipsychotic and/or benzodiazepine after de-escalation has failed', true, 'Correct. When verbal de-escalation fails and there is immediate risk to the patient or others from severe agitation/aggression, rapid tranquillisation (commonly intramuscular lorazepam and/or an antipsychotic such as haloperidol, depending on local protocol and any contraindications) is the appropriate next step to ensure safety, with close physical monitoring afterward.', 5),
('e3000000-0000-0000-0000-000000000042', 'A', 'Routine referral to community mental health services within 4-6 weeks', false, 'Ruled out because postpartum psychosis is a rapidly evolving emergency; routine referral timescales are unsafe and same-day assessment is required.', 1),
('e3000000-0000-0000-0000-000000000042', 'B', 'Advise her to rest and reassess in a fortnight, as new mothers commonly experience sleep disturbance', false, 'Ruled out because although sleep disturbance is common postpartum, the described symptoms (persecutory delusions, possible thought-related hallucinatory experience, insomnia) represent psychosis, not simple tiredness, and require urgent assessment, not reassurance and delay.', 2),
('e3000000-0000-0000-0000-000000000042', 'C', 'Commence combined oral contraception to stabilise hormone levels', false, 'Ruled out because hormonal contraception does not treat postpartum psychosis; the priority is urgent psychiatric assessment and treatment, not hormonal manipulation.', 3),
('e3000000-0000-0000-0000-000000000042', 'D', 'Urgent same-day referral for specialist perinatal psychiatric assessment given the high risk of rapid deterioration', true, 'Correct. New-onset psychotic symptoms within the first 2 weeks postpartum, with a family history of a similar postpartum episode (a recognised risk factor), require urgent same-day specialist perinatal psychiatric assessment, as postpartum psychosis can deteriorate rapidly and carries risk to both mother and infant.', 4),
('e3000000-0000-0000-0000-000000000042', 'E', 'No action needed as her symptoms will likely resolve spontaneously within days', false, 'Ruled out because postpartum psychosis does not reliably resolve spontaneously and carries significant risk if untreated; it requires active urgent psychiatric intervention.', 5),
('e3000000-0000-0000-0000-000000000043', 'A', 'Assess withdrawal severity using a validated tool (e.g. CIWA-Ar) and commence a reducing regimen of chlordiazepoxide', true, 'Correct. This presentation (tremor, anxiety, sweating, tachycardia, hypertension emerging around 24-48 hours after last drink) is consistent with alcohol withdrawal; management involves structured assessment of severity (e.g. CIWA-Ar) and a symptom-triggered or fixed reducing-dose regimen of a long-acting benzodiazepine such as chlordiazepoxide, alongside thiamine supplementation.', 1),
('e3000000-0000-0000-0000-000000000043', 'B', 'Administer intravenous alcohol to prevent withdrawal', false, 'Ruled out because giving alcohol is not appropriate or standard management of alcohol withdrawal in a hospital setting; benzodiazepines are the evidence-based treatment.', 2),
('e3000000-0000-0000-0000-000000000043', 'C', 'No treatment is required as his symptoms are mild and will resolve on their own', false, 'Ruled out because untreated alcohol withdrawal can progress to seizures and delirium tremens; even mild-moderate symptoms should be actively assessed and treated to prevent escalation.', 3),
('e3000000-0000-0000-0000-000000000043', 'D', 'Start haloperidol as the first-line treatment for withdrawal symptoms', false, 'Ruled out because haloperidol does not treat the underlying GABA-glutamate dysregulation of alcohol withdrawal and can lower seizure threshold; benzodiazepines are first-line.', 4),
('e3000000-0000-0000-0000-000000000043', 'E', 'Discharge home immediately with no specific withdrawal management given he is medically stable for surgery', false, 'Ruled out because active, unmanaged alcohol withdrawal risks rapid escalation to seizures or delirium tremens and requires proactive treatment, not discharge without intervention.', 5),
('e3000000-0000-0000-0000-000000000044', 'A', 'Mild alcohol withdrawal; oral chlordiazepoxide on a standard outpatient reducing regimen', false, 'Ruled out because this presentation (confusion, hallucinations, marked autonomic instability) represents severe withdrawal (delirium tremens), a medical emergency requiring urgent, closely monitored inpatient treatment, not a standard outpatient regimen.', 1),
('e3000000-0000-0000-0000-000000000044', 'B', $x$Wernicke's encephalopathy; treat with intravenous thiamine alone with no benzodiazepine$x$, false, $x$Ruled out because although thiamine should be given as good practice in any alcohol-dependent patient, the described clinical picture (confusion, hallucinations, autonomic hyperactivity at 60 hours post-cessation) is delirium tremens, which requires benzodiazepine treatment as the primary urgent intervention; Wernicke's classically features ataxia and ophthalmoplegia rather than this autonomic/hallucinatory picture.$x$, 2),
('e3000000-0000-0000-0000-000000000044', 'C', 'Delirium tremens; urgent high-dose benzodiazepine treatment (e.g. IV/oral diazepam or lorazepam) with close monitoring, ideally in a high-dependency setting', true, 'Correct. Confusion, agitation, visual hallucinations, marked autonomic hyperactivity (tachycardia, hypertension, fever, sweating), and tremor occurring 48-96 hours after alcohol cessation is classic for delirium tremens, a medical emergency with significant mortality if untreated; management requires urgent, often high and titrated doses of benzodiazepines with close monitoring, frequently in a high-dependency or monitored setting.', 3),
('e3000000-0000-0000-0000-000000000044', 'D', 'Acute psychotic episode unrelated to alcohol; start an antipsychotic as sole treatment', false, 'Ruled out because the clear temporal relationship to alcohol cessation and the classic triad of confusion, autonomic hyperactivity, and hallucinations point to delirium tremens, which requires benzodiazepine treatment as first-line, not antipsychotic monotherapy (which does not adequately treat the underlying withdrawal and can lower seizure threshold).', 4),
('e3000000-0000-0000-0000-000000000044', 'E', 'Sepsis; empirical broad-spectrum antibiotics as the priority treatment', false, 'Ruled out because although infection should be considered/excluded, the clinical picture and clear timeline of alcohol withdrawal strongly indicate delirium tremens as the primary diagnosis requiring urgent benzodiazepine treatment.', 5),
('e3000000-0000-0000-0000-000000000045', 'A', 'Korsakoff syndrome, an unavoidable consequence of long-term alcohol use', false, $x$Ruled out because Korsakoff syndrome (chronic amnesic syndrome with confabulation) is a later, often irreversible consequence of untreated/recurrent Wernicke's encephalopathy, not the acute triad described here, and importantly the sequence of care (glucose before thiamine) was a preventable error, not an unavoidable outcome.$x$, 1),
('e3000000-0000-0000-0000-000000000045', 'B', $x$Wernicke's encephalopathy, precipitated by giving glucose before thiamine replacement$x$, true, $x$Correct. The triad of ataxia, nystagmus/ophthalmoplegia, and confusion in a malnourished patient with alcohol dependence is classic for Wernicke's encephalopathy, caused by thiamine deficiency; administering glucose without first giving thiamine can precipitate or worsen Wernicke's encephalopathy, as glucose metabolism consumes remaining thiamine stores, so thiamine should always be given before or with glucose in at-risk patients.$x$, 2),
('e3000000-0000-0000-0000-000000000045', 'C', 'Hepatic encephalopathy due to alcohol-related liver disease', false, $x$Ruled out because there is no mention of liver failure, asterixis, or a preceding precipitant typical of hepatic encephalopathy; the specific triad and clear precipitating error (glucose before thiamine) point to Wernicke's encephalopathy.$x$, 3),
('e3000000-0000-0000-0000-000000000045', 'D', 'Normal expected recovery phase from hypoglycaemia treatment', false, $x$Ruled out because ataxia, nystagmus, and confusion are not expected features of glucose correction; they represent a distinct, serious neurological complication (Wernicke's encephalopathy) requiring urgent thiamine treatment.$x$, 4),
('e3000000-0000-0000-0000-000000000045', 'E', 'Alcohol withdrawal seizure', false, $x$Ruled out because no seizure activity is described; the clinical triad of ataxia, nystagmus, and confusion is specific to Wernicke's encephalopathy rather than a withdrawal seizure.$x$, 5),
('e3000000-0000-0000-0000-000000000046', 'A', 'Flumazenil as the definitive treatment', false, 'Ruled out because flumazenil reverses benzodiazepine (not opioid) toxicity; the clinical picture (pinpoint pupils, respiratory depression, known heroin use) indicates opioid overdose, for which naloxone is indicated.', 1),
('e3000000-0000-0000-0000-000000000046', 'B', 'Activated charcoal', false, 'Ruled out because activated charcoal is used for certain oral ingestions within a limited time window and is not appropriate or effective for parenteral opioid overdose; the priority is airway/breathing support and naloxone.', 2),
('e3000000-0000-0000-0000-000000000046', 'C', 'Intravenous or intramuscular naloxone, with airway support and oxygen', true, $x$Correct. Respiratory depression, pinpoint pupils, and reduced consciousness in the context of known intravenous heroin use is classic for opioid overdose; naloxone is a rapidly acting opioid antagonist that reverses respiratory depression, and should be given promptly alongside airway support, oxygen, and monitoring (with awareness that repeat doses may be needed as naloxone's effect can wear off before the opioid's).$x$, 3),
('e3000000-0000-0000-0000-000000000046', 'D', 'Immediate extubation and discharge once he becomes responsive to a single dose of naloxone', false, $x$Ruled out because naloxone's duration of action is shorter than many opioids, so patients require an observation period after reversal to monitor for re-sedation/recurrence of respiratory depression, not immediate discharge.$x$, 4),
('e3000000-0000-0000-0000-000000000046', 'E', 'High-flow oxygen alone with no naloxone', false, 'Ruled out because oxygen alone does not reverse the underlying opioid-induced respiratory depression; naloxone is required as definitive reversal treatment alongside supportive oxygen therapy.', 5),
('e3000000-0000-0000-0000-000000000047', 'A', 'Intravenous naloxone to reverse his withdrawal symptoms', false, 'Ruled out because naloxone is an opioid antagonist used to reverse opioid overdose/toxicity and would worsen, not treat, opioid withdrawal symptoms.', 1),
('e3000000-0000-0000-0000-000000000047', 'B', 'Reassurance only, with no medical treatment, as opioid withdrawal is not medically significant', false, 'Ruled out because although opioid withdrawal is rarely life-threatening, it is highly distressing and a major driver of relapse; active management with substitution therapy significantly improves outcomes and engagement with treatment.', 2),
('e3000000-0000-0000-0000-000000000047', 'C', 'High-dose benzodiazepines as the primary treatment for opioid withdrawal', false, 'Ruled out because benzodiazepines do not specifically treat opioid withdrawal and carry their own dependence risk; opioid substitution therapy is the appropriate first-line treatment for opioid withdrawal symptoms.', 3),
('e3000000-0000-0000-0000-000000000047', 'D', 'Opioid substitution therapy with methadone or buprenorphine, titrated to control withdrawal symptoms', true, 'Correct. This presentation (yawning, rhinorrhoea, lacrimation, gastrointestinal symptoms, myalgia) is classic opioid withdrawal, which is uncomfortable but rarely life-threatening; first-line management is opioid substitution therapy with methadone or buprenorphine to control withdrawal symptoms and support longer-term recovery, alongside psychosocial support.', 4),
('e3000000-0000-0000-0000-000000000047', 'E', 'Admission to a general medical ward for symptomatic treatment only, with no substitution therapy', false, 'Ruled out because opioid withdrawal is typically managed with specific substitution therapy (methadone/buprenorphine) rather than purely symptomatic treatment on a general ward, and can often be managed in a specialist community drug service or appropriate detoxification setting.', 5),
('e3000000-0000-0000-0000-000000000048', 'A', 'Advise her to remain benzodiazepine-free and manage future seizures with as-required treatment only', false, 'Ruled out because abrupt benzodiazepine withdrawal after long-term high-dose use carries significant risk of further seizures and severe withdrawal; a planned, gradual reduction regimen is required, not abstinence with reactive-only treatment.', 1),
('e3000000-0000-0000-0000-000000000048', 'B', 'Start an antiepileptic drug such as sodium valproate as the primary long-term treatment instead of benzodiazepine tapering', false, 'Ruled out because the underlying issue is benzodiazepine withdrawal, which is specifically treated by reinstating and then gradually tapering a benzodiazepine, not by substituting a different antiepileptic agent as primary treatment.', 2),
('e3000000-0000-0000-0000-000000000048', 'C', 'Discharge with no specific follow-up as the seizure was an isolated event', false, 'Ruled out because she remains at risk of further withdrawal seizures and complications without a structured tapering plan and follow-up; discharge without a management plan is unsafe.', 3),
('e3000000-0000-0000-0000-000000000048', 'D', 'Administer flumazenil to reverse her symptoms', false, 'Ruled out because flumazenil is a benzodiazepine antagonist used to reverse benzodiazepine overdose/toxicity; giving it in the context of withdrawal would worsen, not treat, her withdrawal symptoms and could itself precipitate seizures.', 4),
('e3000000-0000-0000-0000-000000000048', 'E', 'Reintroduce a benzodiazepine (e.g. diazepam) and establish a supervised, gradual dose-reduction regimen', true, 'Correct. Abrupt cessation of long-term, high-dose benzodiazepine use can precipitate life-threatening withdrawal including seizures; management involves reintroducing a benzodiazepine (often converting to diazepam due to its long half-life) followed by a slow, supervised tapering regimen over weeks to months, rather than abrupt discontinuation.', 5),
('e3000000-0000-0000-0000-000000000049', 'A', 'Benzodiazepines', false, 'Ruled out because benzodiazepines are helpful in cocaine toxicity, reducing sympathetic overactivity, agitation, and associated hypertension/tachycardia; they are not contraindicated and are often part of management.', 1),
('e3000000-0000-0000-0000-000000000049', 'B', 'Beta-blockers', true, 'Correct. Beta-blockers should be avoided in cocaine-associated chest pain/myocardial infarction because unopposed alpha-adrenergic stimulation can occur, worsening coronary vasoconstriction and hypertension; benzodiazepines, glyceryl trinitrate, and standard ACS management (aspirin, consideration of PCI) are used instead, with caution regarding specific antiplatelet/anticoagulant choices as per local protocols.', 2),
('e3000000-0000-0000-0000-000000000049', 'C', 'Aspirin', false, 'Ruled out because aspirin remains part of standard acute coronary syndrome management, including in cocaine-associated myocardial infarction, unless there is a specific contraindication.', 3),
('e3000000-0000-0000-0000-000000000049', 'D', 'Glyceryl trinitrate', false, 'Ruled out because GTN can be used to help relieve cocaine-induced coronary vasospasm and chest pain and is not contraindicated, unlike beta-blockers.', 4),
('e3000000-0000-0000-0000-000000000049', 'E', 'Oxygen if hypoxic', false, 'Ruled out because supplemental oxygen for a hypoxic patient is standard supportive care and is not contraindicated in cocaine toxicity.', 5),
('e3000000-0000-0000-0000-000000000050', 'A', 'Arrange a formal assessment for a community (or, given his seizure history, potentially inpatient) medically assisted alcohol withdrawal programme, with prophylactic oral thiamine', true, $x$Correct. Given his heavy daily consumption, morning relief drinking (a marker of physical dependence), and a previous withdrawal seizure (a risk factor for a complicated withdrawal), he requires formal assessment for a structured, medically supervised withdrawal programme (community-based if appropriate, or inpatient given his seizure history) using a reducing benzodiazepine regimen, with prophylactic thiamine to reduce Wernicke's encephalopathy risk.$x$, 1),
('e3000000-0000-0000-0000-000000000050', 'B', 'Advise him to simply stop drinking abruptly on his own at home', false, 'Ruled out because abrupt unsupervised cessation in a dependent drinker, especially with a prior withdrawal seizure, carries significant risk of further seizures or delirium tremens; a supervised, medically managed reduction is required.', 2),
('e3000000-0000-0000-0000-000000000050', 'C', 'Reassure him that no formal treatment is needed as he is motivated to stop', false, 'Ruled out because motivation alone does not mitigate the physical risk of unsupervised withdrawal in a dependent drinker with a prior seizure; formal medical support for withdrawal is required.', 3),
('e3000000-0000-0000-0000-000000000050', 'D', 'Start disulfiram immediately while he continues drinking at his current level', false, 'Ruled out because disulfiram causes a severe reaction with alcohol and is used only after a patient has successfully stopped drinking, as a relapse-prevention agent, not started while actively drinking heavily.', 4),
('e3000000-0000-0000-0000-000000000050', 'E', 'Refer for immediate liver transplant assessment', false, 'Ruled out because there is no evidence provided of decompensated liver disease; the priority is safe, supervised management of his alcohol dependence and withdrawal risk, not transplant assessment.', 5)
insert into question_discriminators (question_id, discriminator_text, sort_order) values
('e3000000-0000-0000-0000-000000000001', 'GAD requires excessive, difficult-to-control worry about multiple domains for at least 6 months with associated physical symptoms (tension, poor sleep, restlessness).', 1),
('e3000000-0000-0000-0000-000000000001', 'Stepped care: education/active monitoring, then low-intensity psychological intervention, then high-intensity CBT or an SSRI, then specialist referral if refractory.', 2),
('e3000000-0000-0000-0000-000000000001', 'SSRIs are first-line drug treatment for GAD; benzodiazepines are avoided for long-term use due to dependence.', 3),
('e3000000-0000-0000-0000-000000000002', 'Panic disorder = recurrent unexpected panic attacks plus persistent worry about further attacks or their consequences, often leading to agoraphobic avoidance.', 1),
('e3000000-0000-0000-0000-000000000002', 'Always exclude organic causes (cardiac, thyroid, hypoglycaemia, substance use) in a first presentation before attributing symptoms to panic disorder.', 2),
('e3000000-0000-0000-0000-000000000002', 'First-line management is CBT; SSRIs (e.g. sertraline) are first-line pharmacological treatment if therapy alone is insufficient; benzodiazepines are avoided long-term.', 3),
('e3000000-0000-0000-0000-000000000003', 'OCD is defined by obsessions (intrusive, unwanted, recognised as excessive) and/or compulsions (repetitive behaviours performed to reduce anxiety), causing significant time loss or distress.', 1),
('e3000000-0000-0000-0000-000000000003', 'CBT with ERP is first-line for mild-moderate OCD; an SSRI (often at higher doses than for depression, e.g. fluoxetine) is added for moderate-severe or if CBT alone is insufficient.', 2),
('e3000000-0000-0000-0000-000000000003', 'Insight is usually preserved in OCD (patient recognises thoughts as irrational), distinguishing it from psychotic disorders.', 3),
('e3000000-0000-0000-0000-000000000004', 'PTSD symptoms: re-experiencing (flashbacks, nightmares), avoidance, hyperarousal, and negative alterations in mood/cognition, persisting beyond one month after trauma.', 1),
('e3000000-0000-0000-0000-000000000004', 'Trauma-focused CBT or eye movement desensitisation and reprocessing (EMDR) are first-line; drug treatment (e.g. venlafaxine or an SSRI) is considered if psychological therapy is declined or ineffective.', 2),
('e3000000-0000-0000-0000-000000000004', 'Watchful waiting is reserved only for mild symptoms present less than 4 weeks post-trauma.', 3),
('e3000000-0000-0000-0000-000000000005', 'Illness anxiety disorder = preoccupation with having a serious illness despite minimal symptoms and reassuring investigations, with high anxiety and checking/reassurance-seeking behaviours.', 1),
('e3000000-0000-0000-0000-000000000005', 'Management is primarily psychological (CBT) with a single, clearly communicated GP as gatekeeper to avoid unnecessary repeat investigations that reinforce anxiety.', 2),
('e3000000-0000-0000-0000-000000000005', 'Distinguish from somatic symptom disorder (focus on distressing physical symptoms) and factitious disorder/malingering (deliberate symptom fabrication).', 3),
('e3000000-0000-0000-0000-000000000006', 'Somatic symptom disorder = one or more distressing somatic symptoms with excessive thoughts, feelings, or behaviours related to the symptoms, persisting despite medical reassurance.', 1),
('e3000000-0000-0000-0000-000000000006', 'Key management principle: continuity with one GP, scheduled (not symptom-triggered) review appointments, and CBT; avoid repeated unnecessary investigations which reinforce illness behaviour.', 2),
('e3000000-0000-0000-0000-000000000006', 'Explaining findings honestly and validating distress (rather than dismissing symptoms) maintains trust and therapeutic engagement.', 3),
('e3000000-0000-0000-0000-000000000007', 'Social anxiety disorder is characterised by fear of scrutiny/negative evaluation in social or performance situations, with avoidance and significant functional impact.', 1),
('e3000000-0000-0000-0000-000000000007', 'First-line treatment is CBT (individual or group) tailored to social anxiety; an SSRI (e.g. sertraline or escitalopram) is used if therapy is insufficient or declined.', 2),
('e3000000-0000-0000-0000-000000000007', 'Distinguish from panic disorder (unprovoked attacks) and agoraphobia (fear tied to inability to escape/get help, not scrutiny).', 3),
('e3000000-0000-0000-0000-000000000008', 'Specific phobia = marked, persistent, excessive fear of a specific object/situation, leading to avoidance and functional impairment, with intact insight that the fear is excessive.', 1),
('e3000000-0000-0000-0000-000000000008', 'Graded/systematic exposure therapy is first-line and highly effective for specific phobias, including needle/blood phobia (with attention to vasovagal response).', 2),
('e3000000-0000-0000-0000-000000000008', 'Medication has a limited role; benzodiazepines are avoided long-term due to dependence and lack of lasting benefit.', 3),
('e3000000-0000-0000-0000-000000000009', 'Acute panic attacks cause hyperventilation-related symptoms (paraesthesia, dizziness) which can mimic serious organic pathology; a first presentation always warrants exclusion of organic causes.', 1),
('e3000000-0000-0000-0000-000000000009', 'In a patient with an established diagnosis and reassuring findings, non-pharmacological reassurance and breathing techniques are first-line; avoid reflexive benzodiazepine use.', 2),
('e3000000-0000-0000-0000-000000000009', 'Definitive longer-term management of panic disorder is CBT +/- SSRI, arranged after the acute episode settles.', 3),
('e3000000-0000-0000-0000-000000000010', 'The Mental Capacity Act two-stage test: (1) is there an impairment/disturbance of mind or brain function; (2) does this cause inability to understand, retain, weigh, or communicate the decision (any one suffices).', 1),
('e3000000-0000-0000-0000-000000000010', 'Capacity is decision-specific and time-specific — assess for the particular decision at hand, not globally.', 2),
('e3000000-0000-0000-0000-000000000010', $x$Absent a valid ADRT or LPA, treatment proceeds on a best-interests basis involving family/carers' views but the final decision rests with the treating clinician (or team).$x$, 3),
('e3000000-0000-0000-0000-000000000011', $x$Best-interests decisions should involve consultation with family/carers, but the decision is made by the responsible clinician/team based on the patient's known wishes, values, and welfare.$x$, 1),
('e3000000-0000-0000-0000-000000000011', 'The Court of Protection is the appropriate route for unresolved serious disputes about best-interests decisions, including contested residence or significant medical treatment.', 2),
('e3000000-0000-0000-0000-000000000011', $x$Family members without a valid Lasting Power of Attorney do not have automatic authority to make decisions on the patient's behalf.$x$, 3),
('e3000000-0000-0000-0000-000000000012', 'Section 2 = admission for assessment, up to 28 days, needs 2 doctors + an AMHP; used when diagnosis/needs are unclear or first presentation/relapse requiring assessment.', 1),
('e3000000-0000-0000-0000-000000000012', 'Section 3 = admission for treatment, up to 6 months (renewable), used when diagnosis and treatment plan are already established.', 2),
('e3000000-0000-0000-0000-000000000012', 'Section 5(2) applies only to existing voluntary inpatients; Section 136 applies to police removing someone from a public place.', 3),
('e3000000-0000-0000-0000-000000000013', 'Section 2 (assessment, up to 28 days, non-renewable) is used first when diagnosis is unclear; Section 3 (treatment, up to 6 months, renewable) follows once diagnosis and treatment needs are established.', 1),
('e3000000-0000-0000-0000-000000000013', $x$Detention under the Mental Health Act requires ongoing justification: a mental disorder of a nature/degree warranting hospital treatment, and that treatment is necessary for the patient's health/safety or protection of others.$x$, 2),
('e3000000-0000-0000-0000-000000000013', $x$The Mental Health Act allows treatment of mental disorder even without capacity/consent, distinct from the Mental Capacity Act's best-interests framework for physical health decisions.$x$, 3),
('e3000000-0000-0000-0000-000000000014', $x$Section 5(2) = doctor's (or nominated deputy's) holding power for a voluntary inpatient already in hospital, lasting up to 72 hours, to allow time for a full Mental Health Act assessment.$x$, 1),
('e3000000-0000-0000-0000-000000000014', $x$It does not authorise treatment against the patient's wishes — only detention pending assessment.$x$, 2),
('e3000000-0000-0000-0000-000000000014', $x$Distinguish from Section 5(4), a nurse's holding power (up to 6 hours) used when no doctor is immediately available.$x$, 3),
('e3000000-0000-0000-0000-000000000015', 'Section 136 = police power to remove a person appearing to have a mental disorder and in need of care/control from a public place to a place of safety for assessment (up to 24 hours, extendable by 12).', 1),
('e3000000-0000-0000-0000-000000000015', 'It does not require a criminal offence; the purpose is safety and psychiatric assessment, not law enforcement.', 2),
('e3000000-0000-0000-0000-000000000015', 'Compare with Section 135, which is a warrant allowing police (with an AMHP) to enter private premises to remove a person for assessment.', 3),
('e3000000-0000-0000-0000-000000000016', 'DoLS authorise a deprivation of liberty (continuous supervision/control, not free to leave) for a person lacking capacity, cared for in a hospital or care home, where this is in their best interests.', 1),
('e3000000-0000-0000-0000-000000000016', $x$The Mental Capacity Act governs decisions and restrictions relating to a person's welfare when they lack capacity; DoLS is the specific safeguard for restrictions amounting to deprivation of liberty.$x$, 2),
('e3000000-0000-0000-0000-000000000016', 'The Mental Health Act is used instead when detention is specifically for assessment/treatment of mental disorder in a hospital setting.', 3),
('e3000000-0000-0000-0000-000000000017', 'An ADRT refusing life-sustaining treatment must be in writing, signed, and witnessed to be valid, and must specifically state it applies even if life is at risk.', 1),
('e3000000-0000-0000-0000-000000000017', 'A valid, applicable ADRT is legally binding and takes precedence over family wishes and clinical judgement about best interests.', 2),
('e3000000-0000-0000-0000-000000000017', 'Check validity (not withdrawn, not superseded by a later LPA appointing a health and welfare attorney) and applicability (matches the current clinical situation) before relying on an ADRT.', 3),
('e3000000-0000-0000-0000-000000000018', 'Gillick competence assesses whether a child under 16 has sufficient maturity and understanding to consent to a specific treatment/decision; it is decision-specific.', 1),
('e3000000-0000-0000-0000-000000000018', 'The Fraser guidelines specifically apply to contraceptive advice/treatment for under-16s, requiring assessment of understanding, likely sexual activity, best interests, and encouragement (but not requirement) to involve parents.', 2),
('e3000000-0000-0000-0000-000000000018', 'Confidentiality should be maintained unless there are safeguarding concerns (e.g. significant power/age imbalance, coercion, or risk of harm), which would warrant further assessment and possible escalation.', 3),
('e3000000-0000-0000-0000-000000000019', 'Anorexia nervosa: significantly low body weight from restriction, intense fear of weight gain/persistent behaviour preventing weight gain, and disturbed self-perception of weight/shape.', 1),
('e3000000-0000-0000-0000-000000000019', 'Amenorrhoea is a common consequence (not a required diagnostic criterion in current classifications) reflecting the impact of low weight on the hypothalamic-pituitary-gonadal axis.', 2),
('e3000000-0000-0000-0000-000000000019', 'Always assess physical risk (bradycardia, hypotension, electrolytes, BMI) and consider specialist eating disorder referral early.', 3),
('e3000000-0000-0000-0000-000000000020', 'Refeeding syndrome risk is highest in severely malnourished patients (e.g. very low BMI, minimal intake for >10 days); prevention involves slow, cautious reintroduction of calories with electrolyte monitoring and supplementation.', 1),
('e3000000-0000-0000-0000-000000000020', 'Classic biochemistry: hypophosphataemia (most characteristic), hypokalaemia, hypomagnesaemia, and fluid retention/oedema.', 2),
('e3000000-0000-0000-0000-000000000020', $x$Thiamine supplementation should be given before/during refeeding to reduce Wernicke's encephalopathy risk in malnourished patients, independent of the refeeding syndrome electrolyte picture.$x$, 3),
('e3000000-0000-0000-0000-000000000021', 'Severe anorexia nervosa carries risk of bradycardia, hypotension, and QTc prolongation due to starvation and electrolyte disturbance, predisposing to life-threatening arrhythmia.', 1),
('e3000000-0000-0000-0000-000000000021', $x$MARSIPAN/junior MARSIPAN guidance identifies specific physical risk parameters (low BMI, bradycardia, prolonged QTc, hypokalaemia/hypophosphataemia) that mandate urgent medical admission, even against the patient's wishes if necessary.$x$, 2),
('e3000000-0000-0000-0000-000000000021', 'Electrolyte correction and cardiac monitoring must occur alongside cautious nutritional rehabilitation, with awareness of refeeding syndrome risk.', 3),
('e3000000-0000-0000-0000-000000000022', 'Bulimia nervosa = recurrent binge eating plus recurrent compensatory behaviour (vomiting, laxatives, excessive exercise, fasting) at least weekly for 3 months, typically with normal/near-normal BMI.', 1),
('e3000000-0000-0000-0000-000000000022', 'First-line treatment is CBT specifically adapted for bulimia (CBT-ED); fluoxetine can reduce binge/purge frequency as an adjunct.', 2),
('e3000000-0000-0000-0000-000000000022', 'Assess for physical complications: dental erosion, hypokalaemia (from vomiting/laxative misuse), parotid swelling, and oesophageal/Mallory-Weiss tears.', 3),
('e3000000-0000-0000-0000-000000000023', 'Binge eating disorder = recurrent binge eating with loss of control and marked distress, WITHOUT the regular compensatory behaviours seen in bulimia nervosa.', 1),
('e3000000-0000-0000-0000-000000000023', 'First-line treatment is guided self-help based on CBT principles, or CBT-ED for higher severity; it is the most common eating disorder and often associated with overweight/obesity.', 2),
('e3000000-0000-0000-0000-000000000023', 'Distinguish from bulimia nervosa primarily by the absence of compensatory behaviours (vomiting, laxatives, excessive exercise).', 3),
('e3000000-0000-0000-0000-000000000024', 'Junior MARSIPAN criteria identify high physical risk in adolescents with eating disorders: significant bradycardia, postural drop, syncope, rapid weight loss, and very low BMI/percentage of expected weight — these mandate urgent medical admission.', 1),
('e3000000-0000-0000-0000-000000000024', 'A young person can refuse treatment, but if this places them at serious risk and capacity/Gillick competence is impaired (which severe malnutrition can cause), parental consent, the Mental Capacity Act, or Mental Health Act routes may be needed to ensure safe treatment.', 2),
('e3000000-0000-0000-0000-000000000024', 'Eating disorders in adolescents require joint medical and specialist eating disorder/CAMHS management, particularly when physical risk is high.', 3),
('e3000000-0000-0000-0000-000000000025', 'Chronic anorexia nervosa with prolonged amenorrhoea causes significant oestrogen deficiency and malnutrition-related hormonal changes, leading to reduced bone mineral density and increased fracture risk, often at a young age.', 1),
('e3000000-0000-0000-0000-000000000025', 'Weight restoration and, in some cases, resumption of menses are the most effective ways to improve bone density; hormone replacement/contraceptive pills alone are not first-line and do not substitute for nutritional rehabilitation.', 2),
('e3000000-0000-0000-0000-000000000025', 'DEXA scanning should be considered in patients with prolonged low weight/amenorrhoea to identify and monitor osteoporosis risk.', 3),
('e3000000-0000-0000-0000-000000000026', 'Anorexia nervosa is treatable as a mental disorder under the Mental Health Act; compulsory nutrition (including nasogastric feeding) can be authorised as treatment for the disorder when detention criteria are met.', 1),
('e3000000-0000-0000-0000-000000000026', 'Capacity can be significantly impaired by the cognitive effects of severe starvation, even when a patient appears superficially able to discuss their decision.', 2),
('e3000000-0000-0000-0000-000000000026', $x$This is a genuinely complex, ethically significant scenario and usually involves senior psychiatric, medical, and sometimes legal input — reflecting its 'advanced' rather than routine foundation-level difficulty.$x$, 3),
('e3000000-0000-0000-0000-000000000027', 'Core symptoms of depression: persistent low mood, anhedonia, and low energy, plus associated symptoms (sleep/appetite change, poor concentration, guilt/worthlessness, psychomotor changes).', 1),
('e3000000-0000-0000-0000-000000000027', 'NICE stepped care: for mild depression, consider low-intensity psychological intervention first; for moderate-severe depression, combine an antidepressant (SSRI first-line) with high-intensity psychological therapy.', 2),
('e3000000-0000-0000-0000-000000000027', 'Always screen for suicidal ideation/risk and psychotic features at every assessment, as these change management urgency.', 3),
('e3000000-0000-0000-0000-000000000028', 'Acute mania: elevated or irritable mood, decreased need for sleep, grandiosity, pressured speech, flight of ideas, distractibility, and increased risk-taking/impulsive behaviour, for at least 7 days (or any duration if hospitalisation required).', 1),
('e3000000-0000-0000-0000-000000000028', 'First-line acute pharmacological treatment for mania is an oral antipsychotic (e.g. olanzapine, risperidone, quetiapine, or haloperidol); lithium/valproate are used for longer-term prophylaxis, not acute rapid control.', 2),
('e3000000-0000-0000-0000-000000000028', 'Antidepressants should be avoided or used with extreme caution in bipolar disorder due to risk of triggering mania or mixed states.', 3),
('e3000000-0000-0000-0000-000000000029', 'NSAIDs (and ACE inhibitors, diuretics, dehydration) reduce renal clearance of lithium and can precipitate toxicity even from previously stable, therapeutic doses.', 1),
('e3000000-0000-0000-0000-000000000029', 'Early lithium toxicity: coarse tremor, nausea, vomiting, diarrhoea; progressing to ataxia, confusion, and seizures/coma at higher levels.', 2),
('e3000000-0000-0000-0000-000000000029', 'Lithium requires regular monitoring of levels (taken 12 hours post-dose), renal function, and thyroid function; interacting drugs should be avoided or used with caution and close monitoring.', 3),
('e3000000-0000-0000-0000-000000000030', 'Postpartum psychosis typically presents rapidly within the first 2 weeks after birth with mood disturbance, psychotic symptoms (delusions, hallucinations), and confusion — it is a psychiatric emergency.', 1),
('e3000000-0000-0000-0000-000000000030', 'Risk assessment must consider risk to both mother and infant; admission to a specialist mother and baby unit is preferred where available to allow safe treatment while supporting attachment.', 2),
('e3000000-0000-0000-0000-000000000030', 'Distinguish from baby blues (mild, self-limiting, no psychosis, resolves within ~2 weeks) and postnatal depression (low mood without psychotic features, typically presenting somewhat later).', 3),
('e3000000-0000-0000-0000-000000000031', 'Severe depression with psychotic features (mood-congruent delusions, e.g. nihilistic/guilt-related beliefs) carries a significantly elevated suicide risk and requires urgent psychiatric admission.', 1),
('e3000000-0000-0000-0000-000000000031', $x$A specific plan, stated intent, and imminent timeframe ('today') are high-risk features on suicide risk assessment that mandate emergency action, not routine follow-up.$x$, 2),
('e3000000-0000-0000-0000-000000000031', 'The Mental Health Act can be used to admit a patient who refuses admission when they have a mental disorder warranting hospital treatment and this is necessary for their health/safety or protection of others.', 3),
('e3000000-0000-0000-0000-000000000032', 'Suicide risk assessment should be structured, exploring ideation, intent, specific plans, access to means, past attempts, and protective factors (support, engagement, future plans).', 1),
('e3000000-0000-0000-0000-000000000032', 'Passive ideation without plan/intent and with good protective factors can often be managed safely in the community with clear safety-netting, rather than automatic admission or detention.', 2),
('e3000000-0000-0000-0000-000000000032', 'Avoid prescribing large quantities of potentially toxic medication in overdose to patients with any suicidal ideation; consider smaller supplies with more frequent review.', 3),
('e3000000-0000-0000-0000-000000000033', 'Serotonin syndrome: triad of altered mental status/agitation, autonomic instability (hyperthermia, sweating, diarrhoea, tachycardia), and neuromuscular abnormalities (hyperreflexia, clonus, tremor), classically with lower-limb predominance of clonus.', 1),
('e3000000-0000-0000-0000-000000000033', $x$Common precipitants include combining an SSRI with another serotonergic drug (e.g. tramadol, triptans, MAOIs, St John's Wort, other antidepressants); onset is typically rapid after starting/increasing the interacting drug.$x$, 2),
('e3000000-0000-0000-0000-000000000033', 'Management is supportive (stop causative agents, cooling, benzodiazepines for agitation), with cyproheptadine considered in severe cases; distinguish from neuroleptic malignant syndrome (rigidity, hyporeflexia, slower onset, associated with antipsychotics).', 3),
('e3000000-0000-0000-0000-000000000034', $x$SSRI/SNRI discontinuation syndrome typically occurs within days of stopping or significantly reducing the dose, especially with shorter half-life drugs (e.g. paroxetine, venlafaxine); fluoxetine's long half-life makes this less common.$x$, 1),
('e3000000-0000-0000-0000-000000000034', $x$Symptoms include dizziness, paraesthesia ('electric shock' sensations), nausea, anxiety, irritability, and sleep disturbance; usually mild-moderate and self-limiting over 1-2 weeks.$x$, 2),
('e3000000-0000-0000-0000-000000000034', 'Antidepressants should be tapered gradually when stopping (rather than abrupt cessation) to reduce the risk and severity of discontinuation symptoms.', 3),
('e3000000-0000-0000-0000-000000000035', 'First-episode psychosis in a young person should prompt urgent referral to an early intervention in psychosis (EIP) service, ideally seen within 2 weeks, as early treatment improves long-term outcomes.', 1),
('e3000000-0000-0000-0000-000000000035', $x$Third-person auditory hallucinations (voices discussing the patient) and bizarre delusions are 'first-rank' type symptoms suggestive of schizophrenia, though a full diagnostic workup (excluding organic/substance causes) is required.$x$, 2),
('e3000000-0000-0000-0000-000000000035', 'Assess and exclude substance misuse and organic causes (e.g. drug-induced psychosis, encephalitis) as part of the specialist assessment.', 3),
('e3000000-0000-0000-0000-000000000036', 'First-rank symptoms of schizophrenia include: third-person auditory hallucinations (running commentary, voices discussing the patient), thought insertion/withdrawal/broadcasting, delusional perception, and somatic passivity.', 1),
('e3000000-0000-0000-0000-000000000036', 'These symptoms are highly suggestive of schizophrenia but not exclusively diagnostic — organic causes and substance-induced psychosis must always be excluded.', 2),
('e3000000-0000-0000-0000-000000000036', 'Distinguishing between thought insertion, withdrawal, and broadcasting is a common source of confusion and testable knowledge point.', 3),
('e3000000-0000-0000-0000-000000000037', 'Acute dystonia (torticollis, oculogyric crisis, laryngeal dystonia) typically occurs within hours to days of starting or increasing an antipsychotic, especially high-potency typical agents like haloperidol.', 1),
('e3000000-0000-0000-0000-000000000037', 'Treatment is prompt administration of an anticholinergic (e.g. procyclidine, benzhexol) which rapidly relieves symptoms.', 2),
('e3000000-0000-0000-0000-000000000037', 'Extrapyramidal side effects spectrum: acute dystonia (early), akathisia, parkinsonism (days-weeks), and tardive dyskinesia (late, often irreversible) — each has a different typical time course and management.', 3),
('e3000000-0000-0000-0000-000000000038', $x$Neuroleptic malignant syndrome: fever, lead-pipe rigidity, autonomic instability, altered mental state, and markedly raised creatine kinase, typically developing over 1-3 days after starting/increasing an antipsychotic (or after abrupt dopaminergic drug withdrawal in Parkinson's disease).$x$, 1),
('e3000000-0000-0000-0000-000000000038', 'Management: stop the antipsychotic immediately, provide supportive care (cooling, IV fluids), and consider dantrolene or bromocriptine in severe cases; ICU-level monitoring may be required.', 2),
('e3000000-0000-0000-0000-000000000038', 'Distinguish from serotonin syndrome (hyperreflexia/clonus, serotonergic drug trigger) and acute dystonia (localised muscle contraction, no fever/CK rise).', 3),
('e3000000-0000-0000-0000-000000000039', 'Clozapine requires mandatory registration with a monitoring service and regular full blood count monitoring (weekly initially, then less frequently) due to the risk of agranulocytosis/neutropenia.', 1),
('e3000000-0000-0000-0000-000000000039', 'A significant drop in neutrophil count requires immediate cessation of clozapine and urgent haematological assessment; clozapine is not usually restarted after this occurs.', 2),
('e3000000-0000-0000-0000-000000000039', 'Clozapine is reserved for treatment-resistant schizophrenia (inadequate response to at least two adequate antipsychotic trials) due to this and other significant side effects (myocarditis, seizures, severe constipation).', 3),
('e3000000-0000-0000-0000-000000000040', 'Antipsychotics, particularly olanzapine and clozapine, carry high risk of weight gain, dyslipidaemia, and type 2 diabetes; annual (at minimum) physical health monitoring (weight/BMI, glucose, lipids, blood pressure) is required for all patients on long-term antipsychotics.', 1),
('e3000000-0000-0000-0000-000000000040', 'Management of emerging metabolic syndrome includes lifestyle advice, considering switching to a lower-risk antipsychotic (e.g. aripiprazole), and treating hyperglycaemia/dyslipidaemia/hypertension as needed.', 2),
('e3000000-0000-0000-0000-000000000040', 'Physical health monitoring in patients with severe mental illness is a key patient safety responsibility, as this population has significantly reduced life expectancy largely due to cardiovascular disease.', 3),
('e3000000-0000-0000-0000-000000000041', 'Rapid tranquillisation is used for acute severe behavioural disturbance when verbal de-escalation has failed and there is immediate risk to the patient or others; it should be the least restrictive effective option.', 1),
('e3000000-0000-0000-0000-000000000041', 'Common regimens include intramuscular lorazepam and/or an antipsychotic (e.g. haloperidol, often with procyclidine available for extrapyramidal effects); choice depends on local protocol, comorbidities, and prior response.', 2),
('e3000000-0000-0000-0000-000000000041', 'Following rapid tranquillisation, close monitoring of physical observations (including oxygen saturation, level of consciousness, and ECG in some cases) is essential due to risks of over-sedation and cardiorespiratory compromise.', 3),
('e3000000-0000-0000-0000-000000000042', 'Postpartum psychosis usually presents within the first 2 weeks after birth and can escalate rapidly, making same-day specialist assessment essential.', 1),
('e3000000-0000-0000-0000-000000000042', 'Risk factors include a personal or family history of postpartum psychosis or bipolar disorder; a family history (as here) should heighten clinical suspicion and urgency.', 2),
('e3000000-0000-0000-0000-000000000042', 'Assessment must consider risk to both mother and baby, with likely admission (ideally to a mother and baby unit) for safe treatment.', 3),
('e3000000-0000-0000-0000-000000000043', 'Alcohol withdrawal typically begins 6-24 hours after the last drink (tremor, anxiety, sweating, tachycardia), progressing without treatment to seizures (peak ~24-48 hours) and delirium tremens (peak ~48-72 hours).', 1),
('e3000000-0000-0000-0000-000000000043', 'First-line treatment is a reducing-dose regimen of a long-acting benzodiazepine (e.g. chlordiazepoxide or diazepam), guided by a symptom-scoring tool such as CIWA-Ar.', 2),
('e3000000-0000-0000-0000-000000000043', $x$Thiamine (Pabrinex) should be given before or alongside glucose administration in patients at risk of Wernicke's encephalopathy due to chronic alcohol use.$x$, 3),
('e3000000-0000-0000-0000-000000000044', 'Delirium tremens typically develops 48-96 hours after the last drink and is characterised by confusion, agitation, vivid hallucinations (often visual, e.g. insects/animals), and marked autonomic hyperactivity — it carries significant mortality if untreated.', 1),
('e3000000-0000-0000-0000-000000000044', 'Treatment is urgent, often high-dose, benzodiazepine therapy (titrated to effect) with close monitoring; some patients require critical care level support.', 2),
('e3000000-0000-0000-0000-000000000044', $x$Thiamine (Pabrinex) should be co-administered to reduce Wernicke's encephalopathy risk, but does not replace benzodiazepine treatment for the withdrawal delirium itself.$x$, 3),
('e3000000-0000-0000-0000-000000000045', $x$Wernicke's encephalopathy triad: confusion, ataxia, and ophthalmoplegia/nystagmus, due to thiamine (vitamin B1) deficiency, classically in chronic alcohol use or malnutrition.$x$, 1),
('e3000000-0000-0000-0000-000000000045', $x$Thiamine must always be given before or with glucose in at-risk patients, as glucose administration alone can precipitate or worsen Wernicke's encephalopathy by depleting remaining thiamine reserves during carbohydrate metabolism.$x$, 2),
('e3000000-0000-0000-0000-000000000045', $x$Untreated or inadequately treated Wernicke's encephalopathy can progress to Korsakoff syndrome, a chronic and often irreversible amnesic disorder with confabulation.$x$, 3),
('e3000000-0000-0000-0000-000000000046', 'Opioid toxicity triad: respiratory depression, pinpoint (miosis) pupils, and reduced consciousness.', 1),
('e3000000-0000-0000-0000-000000000046', 'Naloxone is the specific antidote, given IV/IM/intranasally, with rapid onset but a shorter duration of action than many opioids, so repeat dosing or an infusion and an observation period are often required.', 2),
('e3000000-0000-0000-0000-000000000046', 'Airway, breathing, and circulation support take priority alongside naloxone administration in any opioid overdose.', 3),
('e3000000-0000-0000-0000-000000000047', 'Opioid withdrawal features: yawning, rhinorrhoea, lacrimation, piloerection, gastrointestinal symptoms (cramps, diarrhoea), myalgia, and dysphoria/anxiety — uncomfortable but rarely life-threatening (unlike alcohol/benzodiazepine withdrawal).', 1),
('e3000000-0000-0000-0000-000000000047', 'Opioid substitution therapy (methadone or buprenorphine) is first-line for managing withdrawal and supporting longer-term abstinence/harm reduction, alongside psychosocial support.', 2),
('e3000000-0000-0000-0000-000000000047', 'Naloxone treats opioid overdose/toxicity, not withdrawal, and would worsen withdrawal symptoms if given inappropriately.', 3),
('e3000000-0000-0000-0000-000000000048', 'Benzodiazepine withdrawal, especially after long-term high-dose use, can be life-threatening, with risk of seizures, similar in principle to alcohol withdrawal.', 1),
('e3000000-0000-0000-0000-000000000048', 'Management is reinstatement of a benzodiazepine (commonly converted to diazepam) followed by a slow, individualised dose-reduction regimen over weeks to months, not abrupt cessation.', 2),
('e3000000-0000-0000-0000-000000000048', 'Flumazenil (a benzodiazepine antagonist) is used for benzodiazepine overdose/toxicity, not withdrawal, and is contraindicated in the withdrawal context due to seizure risk.', 3),
('e3000000-0000-0000-0000-000000000049', 'Cocaine causes sympathetic overstimulation, coronary vasospasm, tachycardia, and hypertension, and can precipitate myocardial infarction even in young patients without atherosclerosis.', 1),
('e3000000-0000-0000-0000-000000000049', 'Beta-blockers are specifically avoided in cocaine-associated chest pain/MI due to the risk of unopposed alpha-adrenergic effects worsening vasoconstriction and hypertension.', 2),
('e3000000-0000-0000-0000-000000000049', 'Benzodiazepines are a mainstay of managing cocaine toxicity (agitation, tachycardia, hypertension), alongside standard supportive and ACS-directed care where indicated.', 3),
('e3000000-0000-0000-0000-000000000050', 'Signs of physical alcohol dependence include morning/relief drinking, tolerance, and withdrawal symptoms (including previous withdrawal seizures) — these indicate need for a structured, medically supervised withdrawal plan rather than abrupt self-directed cessation.', 1),
('e3000000-0000-0000-0000-000000000050', 'A previous withdrawal seizure is a risk factor that may favour inpatient rather than community-based detoxification for safety.', 2),
('e3000000-0000-0000-0000-000000000050', $x$Thiamine supplementation should be given prophylactically in patients undergoing alcohol withdrawal to reduce the risk of Wernicke's encephalopathy; relapse-prevention agents (e.g. disulfiram, acamprosate) are considered only after successful withdrawal, not during active heavy drinking.$x$, 3);
